-- =============================================================================
-- LIVING ENGLISH — BASE DE DATOS DE EJERCICIOS POR LECCIÓN (lesson_exercises)
-- Extraído de los 8 libros oficiales (Kids 1, Junior 1, Teens 1-3, Adultos 1-3)
-- Ejecuta este script en el SQL Editor de Supabase.
-- =============================================================================

CREATE TABLE IF NOT EXISTS public.lesson_exercises (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  book_level TEXT NOT NULL,
  lesson_code TEXT NOT NULL,
  lesson_title TEXT NOT NULL,
  lesson_topic TEXT,
  lesson_icon TEXT DEFAULT '📖',
  question_type TEXT NOT NULL DEFAULT 'multiple_choice',
  prompt TEXT NOT NULL,
  options JSONB NOT NULL DEFAULT '[]'::jsonb,
  correct_answer TEXT NOT NULL,
  explanation TEXT,
  order_index INT NOT NULL DEFAULT 1,
  active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_lesson_exercises_book_lesson
  ON public.lesson_exercises (book_level, lesson_code);

ALTER TABLE public.lesson_exercises ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Permitir lectura publica de lesson_exercises" ON public.lesson_exercises;
CREATE POLICY "Permitir lectura publica de lesson_exercises"
  ON public.lesson_exercises
  FOR SELECT
  USING (true);

TRUNCATE TABLE public.lesson_exercises RESTART IDENTITY;

INSERT INTO public.lesson_exercises (
  book_level, lesson_code, lesson_title, lesson_topic, lesson_icon,
  question_type, prompt, options, correct_answer, explanation, order_index
) VALUES
  ('Kids 1', 'L1', 'L1 · Hello! Michi & Chiqui', 'Saludos básicos y decir tu nombre', '🐱', 'multiple_choice', '🐱 Michi says: «Hello! What''s your name?»', '["Hello! I''m Sofi!", "Goodbye!", "Red and blue!", "One, two, three!"]'::jsonb, 'Hello! I''m Sofi!', 'Cuando nos preguntan «What''s your name?», respondemos «I''m + nuestro nombre».', 1),
  ('Kids 1', 'L1', 'L1 · Hello! Michi & Chiqui', 'Saludos básicos y decir tu nombre', '🐱', 'multiple_choice', '👋 When class finishes and we go home, we wave and say:', '["Goodbye! See you soon!", "Good morning!", "Hello!", "What''s your name?"]'::jsonb, 'Goodbye! See you soon!', 'Para despedirnos decimos «Goodbye! / Bye! / See you soon!».', 2),
  ('Kids 1', 'L1', 'L1 · Hello! Michi & Chiqui', 'Saludos básicos y decir tu nombre', '🐱', 'multiple_choice', '👧 «Girl» means niña, and 👦 «Boy» means ___.', '["niño", "maestro", "gatito", "amigo"]'::jsonb, 'niño', 'Girl = niña, Boy = niño, Friend = amigo/a.', 3),
  ('Kids 1', 'L2', 'L2 · My Classroom', 'Útiles escolares y objetos del salón', '✏️', 'multiple_choice', '✏️ What do we use to write and draw in our notebook?', '["a pencil", "a chair", "a door", "a window"]'::jsonb, 'a pencil', '✏️ «Pencil» es lápiz.', 1),
  ('Kids 1', 'L2', 'L2 · My Classroom', 'Útiles escolares y objetos del salón', '✏️', 'multiple_choice', '📖 We open our ___ to read stories in class.', '["book", "bag", "chair", "table"]'::jsonb, 'book', '📖 «Book» significa libro.', 2),
  ('Kids 1', 'L2', 'L2 · My Classroom', 'Útiles escolares y objetos del salón', '✏️', 'multiple_choice', '🎒 Where do you carry your books and crayons to school?', '["in my schoolbag", "on the window", "under the shoe", "in the pencil"]'::jsonb, 'in my schoolbag', '🎒 «Bag / Schoolbag» es el morral o bolso escolar.', 3),
  ('Kids 1', 'L3', 'L3 · Colours', 'Colores principales en inglés', '🌈', 'multiple_choice', '🍎 An apple is ___, and 🍌 a banana is ___.', '["red / yellow", "blue / purple", "pink / black", "white / brown"]'::jsonb, 'red / yellow', 'Red = rojo (🍎) y Yellow = amarillo (🍌).', 1),
  ('Kids 1', 'L3', 'L3 · Colours', 'Colores principales en inglés', '🌈', 'multiple_choice', '🐸 What colour is a little frog and the grass?', '["green", "pink", "orange", "purple"]'::jsonb, 'green', '🐸 «Green» significa verde.', 2),
  ('Kids 1', 'L3', 'L3 · Colours', 'Colores principales en inglés', '🌈', 'multiple_choice', '🍇 Grapes are ___ and 🍊 an orange is ___.', '["purple / orange", "black / white", "blue / red", "yellow / pink"]'::jsonb, 'purple / orange', 'Purple = morado (🍇) y Orange = naranja (🍊).', 3),
  ('Kids 1', 'L4', 'L4 · Numbers 1–10', 'Contar del 1 al 10 en inglés', '🔟', 'multiple_choice', 'Count in order: One, two, three, ___, five!', '["four (4)", "six (6)", "eight (8)", "ten (10)"]'::jsonb, 'four (4)', '1 = one, 2 = two, 3 = three, 4 = four, 5 = five.', 1),
  ('Kids 1', 'L4', 'L4 · Numbers 1–10', 'Contar del 1 al 10 en inglés', '🔟', 'multiple_choice', '🖐️ How many fingers do you have on TWO hands?', '["ten (10)", "five (5)", "seven (7)", "three (3)"]'::jsonb, 'ten (10)', 'En las dos manos tenemos 10 dedos: «ten».', 2),
  ('Kids 1', 'L4', 'L4 · Numbers 1–10', 'Contar del 1 al 10 en inglés', '🔟', 'multiple_choice', 'Count: Six, seven, ___, nine, ten!', '["eight (8)", "two (2)", "four (4)", "one (1)"]'::jsonb, 'eight (8)', 'Después de seven (7) viene eight (8).', 3),
  ('Kids 1', 'L5', 'L5 · My Body', 'Partes del cuerpo y la cara', '✋', 'multiple_choice', '👀 I see with my ___ and 👂 I listen with my ___.', '["eyes / ears", "nose / mouth", "hands / feet", "head / toes"]'::jsonb, 'eyes / ears', 'Eyes = ojos (👀) y Ears = orejas (👂).', 1),
  ('Kids 1', 'L5', 'L5 · My Body', 'Partes del cuerpo y la cara', '✋', 'multiple_choice', '👏 Clap your ___ and 🦶 stomp your ___!', '["hands / feet", "ears / eyes", "nose / head", "mouth / hair"]'::jsonb, 'hands / feet', 'Aplaudimos con las manos («hands») y pisamos fuerte con los pies («feet»).', 2),
  ('Kids 1', 'L5', 'L5 · My Body', 'Partes del cuerpo y la cara', '✋', 'multiple_choice', '👃 What part of your face do you use to smell a flower?', '["my nose", "my knees", "my shoulders", "my toes"]'::jsonb, 'my nose', '👃 «Nose» es la nariz.', 3),
  ('Kids 1', 'L6', 'L6 · Feelings', 'Emociones y cómo me siento hoy', '😀', 'multiple_choice', '😀 When I smile and play with my friends, I am ___!', '["happy", "sad", "angry", "sleepy"]'::jsonb, 'happy', '😀 «Happy» significa feliz.', 1),
  ('Kids 1', 'L6', 'L6 · Feelings', 'Emociones y cómo me siento hoy', '😀', 'multiple_choice', '🥱 It is late at night and I want to go to bed. I am ___.', '["sleepy", "hungry", "happy", "scared"]'::jsonb, 'sleepy', '🥱 «Sleepy» significa tener sueño.', 2),
  ('Kids 1', 'L6', 'L6 · Feelings', 'Emociones y cómo me siento hoy', '😀', 'multiple_choice', '🍕 My tummy is rumbling and I want to eat pizza! I am ___.', '["hungry", "angry", "sad", "cold"]'::jsonb, 'hungry', '«Hungry» significa tener hambre.', 3),
  ('Kids 1', 'L7', 'L7 · My Family', 'Miembros de la familia', '🏡', 'multiple_choice', '👩 «Mom» is mamá, and 👨 «___» is papá.', '["Dad", "Brother", "Baby", "Sister"]'::jsonb, 'Dad', 'Mom / Mother = mamá; Dad / Father = papá.', 1),
  ('Kids 1', 'L7', 'L7 · My Family', 'Miembros de la familia', '🏡', 'multiple_choice', '👵 My mom''s mother is my ___, and 👴 my mom''s father is my ___.', '["grandma / grandpa", "sister / brother", "aunt / baby", "mom / dad"]'::jsonb, 'grandma / grandpa', 'Grandma = abuela (👵) y Grandpa = abuelo (👴).', 2),
  ('Kids 1', 'L7', 'L7 · My Family', 'Miembros de la familia', '🏡', 'multiple_choice', '👶 The smallest member of the family is the ___.', '["baby", "grandpa", "teacher", "doctor"]'::jsonb, 'baby', '👶 «Baby» es el bebé de la familia.', 3),
  ('Kids 1', 'L8', 'L8 · Pets & Farm Animals', 'Mascotas y animales de la granja', '🐶', 'multiple_choice', '🐶 Which pet barks «Woof! Woof!» and wags its tail?', '["a dog", "a cat", "a fish", "a duck"]'::jsonb, 'a dog', '🐶 «Dog» es perro.', 1),
  ('Kids 1', 'L8', 'L8 · Pets & Farm Animals', 'Mascotas y animales de la granja', '🐶', 'multiple_choice', '🐷 Which pink farm animal loves mud and says «Oink»?', '["a pig", "a horse", "a sheep", "a bird"]'::jsonb, 'a pig', '🐷 «Pig» es cerdito.', 2),
  ('Kids 1', 'L8', 'L8 · Pets & Farm Animals', 'Mascotas y animales de la granja', '🐶', 'multiple_choice', '🐱 Michi is a little kitten that says «Meow!». Michi is a ___.', '["cat", "dog", "cow", "duck"]'::jsonb, 'cat', '🐱 «Cat» es gato y «kitten» es gatito.', 3),
  ('Kids 1', 'L9', 'L9 · At the Zoo', 'Animales del zoológico', '🐘', 'multiple_choice', '🐘 Which big grey animal has huge ears and a long trunk?', '["an elephant", "a monkey", "a lion", "a frog"]'::jsonb, 'an elephant', '🐘 «Elephant» es el elefante.', 1),
  ('Kids 1', 'L9', 'L9 · At the Zoo', 'Animales del zoológico', '🐘', 'multiple_choice', '🐵 Which funny animal loves bananas and climbs trees?', '["a monkey", "a zebra", "a fish", "a turtle"]'::jsonb, 'a monkey', '🐵 «Monkey» es el mono.', 2),
  ('Kids 1', 'L9', 'L9 · At the Zoo', 'Animales del zoológico', '🐘', 'multiple_choice', '🦁 Who is called the King of the Jungle and roars loudly?', '["the lion", "the duck", "the rabbit", "the sheep"]'::jsonb, 'the lion', '🦁 «Lion» es el león.', 3),
  ('Kids 1', 'L10', 'L10 · My Toys', 'Juguetes favoritos', '🧸', 'multiple_choice', '⚽ What round toy do we kick when we play football?', '["a ball", "a doll", "a kite", "a puzzle"]'::jsonb, 'a ball', '⚽ «Ball» es pelota o balón.', 1),
  ('Kids 1', 'L10', 'L10 · My Toys', 'Juguetes favoritos', '🧸', 'multiple_choice', '🪁 Which toy flies high up in the sky when it is windy?', '["a kite", "a teddy bear", "a train", "a bike"]'::jsonb, 'a kite', '🪁 «Kite» es cometa o papagayo.', 2),
  ('Kids 1', 'L10', 'L10 · My Toys', 'Juguetes favoritos', '🧸', 'multiple_choice', '🧸 A soft, cuddly toy bear is called a ___.', '["teddy bear", "robot", "car", "drum"]'::jsonb, 'teddy bear', '🧸 «Teddy bear» es osito de peluche.', 3),
  ('Kids 1', 'L11', 'L11 · Yummy Food', 'Comidas, frutas y bebidas que me gustan (I like...)', '🍕', 'multiple_choice', '🍦 On a hot day, I love eating cold sweet ___!', '["ice cream", "soup", "bread", "broccoli"]'::jsonb, 'ice cream', '🍦 «Ice cream» es helado.', 1),
  ('Kids 1', 'L11', 'L11 · Yummy Food', 'Comidas, frutas y bebidas que me gustan (I like...)', '🍕', 'multiple_choice', '🥛 What white drink comes from a cow and is great for breakfast?', '["milk", "orange juice", "pizza", "apple"]'::jsonb, 'milk', '🥛 «Milk» es leche.', 2),
  ('Kids 1', 'L11', 'L11 · Yummy Food', 'Comidas, frutas y bebidas que me gustan (I like...)', '🍕', 'multiple_choice', '😋 How do you say «¡Me gustan las manzanas!» in English?', '["I like apples!", "I am an apple!", "Goodbye apples!", "Where is the apple?"]'::jsonb, 'I like apples!', '«I like...!» significa «¡Me gusta(n)...!».', 3),
  ('Kids 1', 'L12', 'L12 · Shapes & Party Time!', 'Figuras geométricas y vocabulario de fiesta', '🎉', 'multiple_choice', '⭐ What bright shape shines in the night sky and goes on your sticker chart?', '["a star", "a square", "a triangle", "a box"]'::jsonb, 'a star', '⭐ «Star» significa estrella.', 1),
  ('Kids 1', 'L12', 'L12 · Shapes & Party Time!', 'Figuras geométricas y vocabulario de fiesta', '🎉', 'multiple_choice', '❤️ Which shape represents love?', '["a heart", "a circle", "a square", "a rectangle"]'::jsonb, 'a heart', '❤️ «Heart» significa corazón.', 2),
  ('Kids 1', 'L12', 'L12 · Shapes & Party Time!', 'Figuras geométricas y vocabulario de fiesta', '🎉', 'multiple_choice', '🎈 At our Show Day party, we decorate the classroom with colorful ___!', '["balloons", "pencils", "shoes", "erasers"]'::jsonb, 'balloons', '🎈 «Balloons» son globos de fiesta.', 3),
  ('Junior 1', 'L1', 'Lesson 1 · Hello! The Alphabet & Greetings', 'Saludos en inglés, despedidas y el abecedario A–Z', '👋', 'multiple_choice', 'What do you say when you wake up in the morning?', '["Good morning!", "Good night!", "Goodbye!", "Good evening!"]'::jsonb, 'Good morning!', 'Por la mañana saludamos diciendo «Good morning!» (¡Buenos días!).', 1),
  ('Junior 1', 'L1', 'Lesson 1 · Hello! The Alphabet & Greetings', 'Saludos en inglés, despedidas y el abecedario A–Z', '👋', 'multiple_choice', 'What do you say right before going to sleep at night?', '["Good night!", "Good morning!", "Good afternoon!", "Hello!"]'::jsonb, 'Good night!', 'Al despedirnos para ir a dormir decimos «Good night!».', 2),
  ('Junior 1', 'L1', 'Lesson 1 · Hello! The Alphabet & Greetings', 'Saludos en inglés, despedidas y el abecedario A–Z', '👋', 'multiple_choice', 'A: Hello! How are you? — B: ___', '["I''m fine, thank you!", "I''m ten years old.", "It''s blue.", "Goodbye!"]'::jsonb, 'I''m fine, thank you!', 'A la pregunta «How are you?» (¿Cómo estás?) respondemos «I''m fine, thank you!».', 3),
  ('Junior 1', 'L1', 'Lesson 1 · Hello! The Alphabet & Greetings', 'Saludos en inglés, despedidas y el abecedario A–Z', '👋', 'multiple_choice', 'Which of these letters are all VOWELS (vocales)?', '["A, E, I, O, U", "B, C, D, F, G", "A, B, C, D, E", "X, Y, Z, W, V"]'::jsonb, 'A, E, I, O, U', 'Las 5 vocales del inglés son A, E, I, O, U.', 4),
  ('Junior 1', 'L2', 'Lesson 2 · Numbers 1–20 & My Age', 'Números del 1 al 20 y cómo decir tu edad', '🔢', 'multiple_choice', 'Which word represents the number «12»?', '["twelve", "twenty", "two", "eleven"]'::jsonb, 'twelve', '11 = eleven, 12 = twelve, 20 = twenty.', 1),
  ('Junior 1', 'L2', 'Lesson 2 · Numbers 1–20 & My Age', 'Números del 1 al 20 y cómo decir tu edad', '🔢', 'multiple_choice', 'Ten + Five = ___', '["fifteen", "fifty", "fourteen", "sixteen"]'::jsonb, 'fifteen', '10 (ten) + 5 (five) = 15 (fifteen).', 2),
  ('Junior 1', 'L2', 'Lesson 2 · Numbers 1–20 & My Age', 'Números del 1 al 20 y cómo decir tu edad', '🔢', 'multiple_choice', 'A: How old are you, Leo? — B: ___', '["I''m ten years old.", "I have ten years.", "My name is Leo.", "I''m fine, thanks."]'::jsonb, 'I''m ten years old.', 'En inglés la edad se dice con el verbo To Be («I''m ten years old»), nunca con have.', 3),
  ('Junior 1', 'L2', 'Lesson 2 · Numbers 1–20 & My Age', 'Números del 1 al 20 y cómo decir tu edad', '🔢', 'multiple_choice', 'What number comes after nineteen (19)?', '["twenty (20)", "eighteen (18)", "twelve (12)", "thirteen (13)"]'::jsonb, 'twenty (20)', 'Después de nineteen (19) viene twenty (20).', 4),
  ('Junior 1', 'L3', 'Lesson 3 · Colours & Shapes', 'Colores, figuras geométricas y describir objetos', '🎨', 'multiple_choice', 'If you mix RED and YELLOW, what colour do you get?', '["orange", "purple", "green", "pink"]'::jsonb, 'orange', 'Rojo (red) + amarillo (yellow) forman el color naranja (orange).', 1),
  ('Junior 1', 'L3', 'Lesson 3 · Colours & Shapes', 'Colores, figuras geométricas y describir objetos', '🎨', 'multiple_choice', 'A shape with 3 sides is a ___, and a round shape like the sun is a ___.', '["triangle / circle", "square / rectangle", "star / diamond", "circle / square"]'::jsonb, 'triangle / circle', 'Un triángulo (triangle) tiene 3 lados y un círculo (circle) es redondo.', 2),
  ('Junior 1', 'L3', 'Lesson 3 · Colours & Shapes', 'Colores, figuras geométricas y describir objetos', '🎨', 'multiple_choice', 'What colour is the sky on a sunny day?', '["blue", "green", "brown", "black"]'::jsonb, 'blue', 'El cielo despejado es azul («blue»).', 3),
  ('Junior 1', 'L3', 'Lesson 3 · Colours & Shapes', 'Colores, figuras geométricas y describir objetos', '🎨', 'multiple_choice', 'How do you say «una estrella amarilla» in English?', '["a yellow star", "a star yellow", "an yellow star", "yellow a star"]'::jsonb, 'a yellow star', 'En inglés el color va ANTES de la figura: «a yellow star».', 4),
  ('Junior 1', 'L4', 'Lesson 4 · On the Farm', 'Animales de la granja y uso de There is / There are', '🐮', 'multiple_choice', 'Which farm animal gives us milk and says «Moo»?', '["a cow", "a duck", "a hen", "a horse"]'::jsonb, 'a cow', 'La vaca se dice «cow» en inglés.', 1),
  ('Junior 1', 'L4', 'Lesson 4 · On the Farm', 'Animales de la granja y uso de There is / There are', '🐮', 'multiple_choice', 'On the farm, ___ one brown horse and ___ three white sheep.', '["there is / there are", "there are / there is", "is / are", "have / has"]'::jsonb, 'there is / there are', 'Usamos «there is» para 1 solo animal/objeto y «there are» para 2 o más.', 2),
  ('Junior 1', 'L4', 'Lesson 4 · On the Farm', 'Animales de la granja y uso de There is / There are', '🐮', 'multiple_choice', 'Which bird lives on the farm, swims in the pond, and says «Quack»?', '["a duck", "a pig", "a rabbit", "a goat"]'::jsonb, 'a duck', 'El pato se dice «duck».', 3),
  ('Junior 1', 'L4', 'Lesson 4 · On the Farm', 'Animales de la granja y uso de There is / There are', '🐮', 'multiple_choice', 'What is the plural of «sheep»?', '["sheep", "sheeps", "sheepes", "shoop"]'::jsonb, 'sheep', '«Sheep» (oveja/ovejas) se escribe igual en singular y en plural: one sheep, three sheep.', 4),
  ('Junior 1', 'L5', 'Lesson 5 · Wild Animals (Can / Can''t)', 'Animales salvajes y lo que pueden o no pueden hacer (can / can''t)', '🦁', 'multiple_choice', 'Which wild animal has a very long neck and eats leaves from tall trees?', '["a giraffe", "a crocodile", "a monkey", "a snake"]'::jsonb, 'a giraffe', 'La jirafa («giraffe») tiene el cuello muy largo.', 1),
  ('Junior 1', 'L5', 'Lesson 5 · Wild Animals (Can / Can''t)', 'Animales salvajes y lo que pueden o no pueden hacer (can / can''t)', '🦁', 'multiple_choice', 'A bird ___ fly in the sky, but an elephant ___ fly.', '["can / can''t", "can''t / can", "is / isn''t", "has / hasn''t"]'::jsonb, 'can / can''t', '«Can» significa que puede hacerlo y «can''t» que no puede hacerlo.', 2),
  ('Junior 1', 'L5', 'Lesson 5 · Wild Animals (Can / Can''t)', 'Animales salvajes y lo que pueden o no pueden hacer (can / can''t)', '🦁', 'multiple_choice', 'A snake has no legs, so it ___ walk, but it ___ slither!', '["can''t / can", "can / can''t", "isn''t / is", "don''t / do"]'::jsonb, 'can''t / can', 'Una serpiente no puede caminar (can''t walk), pero sí puede deslizarse (can slither).', 3),
  ('Junior 1', 'L5', 'Lesson 5 · Wild Animals (Can / Can''t)', 'Animales salvajes y lo que pueden o no pueden hacer (can / can''t)', '🦁', 'multiple_choice', 'A: Can a monkey climb trees? — B: ___', '["Yes, it can!", "Yes, it is.", "No, it doesn''t.", "Yes, I am."]'::jsonb, 'Yes, it can!', 'Las preguntas con «Can it...?» se responden con «Yes, it can / No, it can''t».', 4),
  ('Junior 1', 'L6', 'Lesson 6 · Under the Sea', 'Animales marinos y el océano', '🐬', 'multiple_choice', 'Which sea animal has eight arms (tentacles)?', '["an octopus", "a shark", "a whale", "a seahorse"]'::jsonb, 'an octopus', 'El pulpo («octopus») tiene 8 tentáculos.', 1),
  ('Junior 1', 'L6', 'Lesson 6 · Under the Sea', 'Animales marinos y el océano', '🐬', 'multiple_choice', 'Which is the biggest animal in the ocean?', '["the blue whale", "the crab", "the starfish", "the clownfish"]'::jsonb, 'the blue whale', 'La ballena azul («blue whale») es el animal más grande del océano.', 2),
  ('Junior 1', 'L6', 'Lesson 6 · Under the Sea', 'Animales marinos y el océano', '🐬', 'multiple_choice', 'A ___ walks sideways on the beach and has two claws.', '["crab", "dolphin", "jellyfish", "shark"]'::jsonb, 'crab', 'El cangrejo se dice «crab» en inglés.', 3),
  ('Junior 1', 'L6', 'Lesson 6 · Under the Sea', 'Animales marinos y el océano', '🐬', 'multiple_choice', 'Dolphins are very smart and they live ___ the sea.', '["in", "on", "underneath of", "at"]'::jsonb, 'in', 'Decimos «in the sea / in the ocean».', 4),
  ('Junior 1', 'L7', 'Lesson 7 · Bugs & Minibeasts', 'Insectos, bichitos y preposiciones de lugar', '🐝', 'multiple_choice', 'Which insect makes sweet honey and is yellow and black?', '["a bee", "an ant", "a spider", "a snail"]'::jsonb, 'a bee', 'La abeja («bee») produce miel («honey»).', 1),
  ('Junior 1', 'L7', 'Lesson 7 · Bugs & Minibeasts', 'Insectos, bichitos y preposiciones de lugar', '🐝', 'multiple_choice', 'A caterpillar turns into a colorful ___!', '["butterfly", "ladybug", "spider", "worm"]'::jsonb, 'butterfly', 'La oruga (caterpillar) se transforma en mariposa («butterfly»).', 2),
  ('Junior 1', 'L7', 'Lesson 7 · Bugs & Minibeasts', 'Insectos, bichitos y preposiciones de lugar', '🐝', 'multiple_choice', 'How many legs does a spider have?', '["eight (8)", "six (6)", "four (4)", "ten (10)"]'::jsonb, 'eight (8)', 'Las arañas (spiders) tienen 8 patas.', 3),
  ('Junior 1', 'L7', 'Lesson 7 · Bugs & Minibeasts', 'Insectos, bichitos y preposiciones de lugar', '🐝', 'multiple_choice', 'A small red bug with black spots is called a ___.', '["ladybug", "grasshopper", "dragonfly", "mosquito"]'::jsonb, 'ladybug', 'La mariquita se llama «ladybug» (o ladybird).', 4),
  ('Junior 1', 'L8', 'Lesson 8 · My Things: A or An?', 'Objetos escolares y personales, uso de A vs. AN', '🎒', 'multiple_choice', 'In my schoolbag, I have ___ pencil, ___ notebook, and ___ eraser.', '["a / a / an", "an / a / a", "a / an / an", "a / a / a"]'::jsonb, 'a / a / an', 'Usamos «an» antes de vocal (an eraser) y «a» antes de consonante (a pencil, a notebook).', 1),
  ('Junior 1', 'L8', 'Lesson 8 · My Things: A or An?', 'Objetos escolares y personales, uso de A vs. AN', '🎒', 'multiple_choice', 'It''s raining! Take ___ umbrella and ___ raincoat.', '["an / a", "a / an", "a / a", "an / an"]'::jsonb, 'an / a', '«Umbrella» empieza con sonido vocálico (an umbrella) y «raincoat» con consonante (a raincoat).', 2),
  ('Junior 1', 'L8', 'Lesson 8 · My Things: A or An?', 'Objetos escolares y personales, uso de A vs. AN', '🎒', 'multiple_choice', 'She is eating ___ apple and ___ banana.', '["an / a", "a / an", "an / an", "a / a"]'::jsonb, 'an / a', '«An apple» (empieza con vocal a) y «a banana» (empieza con consonante b).', 3),
  ('Junior 1', 'L8', 'Lesson 8 · My Things: A or An?', 'Objetos escolares y personales, uso de A vs. AN', '🎒', 'multiple_choice', 'What do you use to cut paper in art class?', '["scissors", "a ruler", "a crayon", "an eraser"]'::jsonb, 'scissors', 'Las tijeras se dicen «scissors» en inglés.', 4),
  ('Junior 1', 'L9', 'Lesson 9 · Days of the Week', 'Los 7 días de la semana y actividades semanales', '📅', 'multiple_choice', 'What day comes after Tuesday and before Thursday?', '["Wednesday", "Monday", "Friday", "Sunday"]'::jsonb, 'Wednesday', 'El orden es Monday, Tuesday, Wednesday, Thursday, Friday.', 1),
  ('Junior 1', 'L9', 'Lesson 9 · Days of the Week', 'Los 7 días de la semana y actividades semanales', '📅', 'multiple_choice', 'Which two days form the weekend (fin de semana)?', '["Saturday and Sunday", "Monday and Friday", "Tuesday and Thursday", "Friday and Monday"]'::jsonb, 'Saturday and Sunday', 'El fin de semana está formado por «Saturday» (sábado) y «Sunday» (domingo).', 2),
  ('Junior 1', 'L9', 'Lesson 9 · Days of the Week', 'Los 7 días de la semana y actividades semanales', '📅', 'multiple_choice', 'We play football ___ Fridays.', '["on", "in", "at", "to"]'::jsonb, 'on', 'Con los días de la semana siempre usamos la preposición «on» (on Monday, on Fridays).', 3),
  ('Junior 1', 'L9', 'Lesson 9 · Days of the Week', 'Los 7 días de la semana y actividades semanales', '📅', 'multiple_choice', 'In English, days of the week always start with a ___ letter.', '["capital (mayúscula)", "small (minúscula)", "silent", "number"]'::jsonb, 'capital (mayúscula)', 'En inglés los días de la semana y los meses se escriben SIEMPRE con letra inicial mayúscula (Monday, Friday).', 4),
  ('Junior 1', 'L10', 'Lesson 10 · Months & Birthdays', 'Los 12 meses del año y cuándo es tu cumpleaños', '🎂', 'multiple_choice', 'What is the first month of the year, and what is the last month?', '["January / December", "March / November", "February / October", "January / August"]'::jsonb, 'January / December', 'El primer mes es «January» (enero) y el último es «December» (diciembre).', 1),
  ('Junior 1', 'L10', 'Lesson 10 · Months & Birthdays', 'Los 12 meses del año y cuándo es tu cumpleaños', '🎂', 'multiple_choice', 'A: When is your birthday? — B: My birthday is ___ May.', '["in", "on", "at", "for"]'::jsonb, 'in', 'Cuando decimos solamente el mes (sin el número del día), usamos la preposición «in» (in May).', 2),
  ('Junior 1', 'L10', 'Lesson 10 · Months & Birthdays', 'Los 12 meses del año y cuándo es tu cumpleaños', '🎂', 'multiple_choice', 'Which month comes right after July?', '["August", "June", "September", "April"]'::jsonb, 'August', 'Después de July (julio) viene August (agosto).', 3),
  ('Junior 1', 'L10', 'Lesson 10 · Months & Birthdays', 'Los 12 meses del año y cuándo es tu cumpleaños', '🎂', 'multiple_choice', 'Halloween is celebrated in ___, and Christmas is in ___.', '["October / December", "November / January", "September / December", "August / July"]'::jsonb, 'October / December', 'Halloween se celebra en «October» y Navidad en «December».', 4),
  ('Junior 1', 'L11', 'Lesson 11 · Seasons & Weather', 'Las 4 estaciones del año y el clima', '🌦️', 'multiple_choice', 'In ___, it is very hot and sunny, and we go to the beach!', '["summer", "winter", "autumn", "rainy"]'::jsonb, 'summer', 'El verano («summer») es la estación más calurosa y soleada.', 1),
  ('Junior 1', 'L11', 'Lesson 11 · Seasons & Weather', 'Las 4 estaciones del año y el clima', '🌦️', 'multiple_choice', 'In ___, flowers bloom and trees turn green again.', '["spring", "winter", "autumn", "snowy"]'::jsonb, 'spring', 'En la primavera («spring») florecen las plantas.', 2),
  ('Junior 1', 'L11', 'Lesson 11 · Seasons & Weather', 'Las 4 estaciones del año y el clima', '🌦️', 'multiple_choice', 'A: How''s the weather today? — B: Take your umbrella, it''s ___!', '["rainy", "sunny", "hot", "dry"]'::jsonb, 'rainy', 'Si necesitas paraguas (umbrella), el clima está lluvioso («rainy»).', 3),
  ('Junior 1', 'L11', 'Lesson 11 · Seasons & Weather', 'Las 4 estaciones del año y el clima', '🌦️', 'multiple_choice', 'In ___, it is very cold and snowy in many countries.', '["winter", "summer", "spring", "hot"]'::jsonb, 'winter', 'El invierno se dice «winter».', 4),
  ('Junior 1', 'L12', 'Lesson 12 · All About Me & My Family', 'Presentación personal completa y miembros de la familia', '🌟', 'multiple_choice', 'Complete the presentation: «Hello! ___ name is Sofi. I ___ 9 years old.»', '["My / am", "I / have", "Me / is", "My / have"]'::jsonb, 'My / am', 'Decimos «My name is...» (Mi nombre es...) y «I am 9 years old» (Tengo 9 años).', 1),
  ('Junior 1', 'L12', 'Lesson 12 · All About Me & My Family', 'Presentación personal completa y miembros de la familia', '🌟', 'multiple_choice', 'My mother and my father are my ___.', '["parents", "grandparents", "cousins", "siblings"]'::jsonb, 'parents', '«Parents» significa padres (mamá y papá); «grandparents» significa abuelos.', 2),
  ('Junior 1', 'L12', 'Lesson 12 · All About Me & My Family', 'Presentación personal completa y miembros de la familia', '🌟', 'multiple_choice', 'A: What is your favorite animal? — B: ___', '["My favorite animal is the dolphin.", "I am ten years old.", "I live in Venezuela.", "Yes, I do."]'::jsonb, 'My favorite animal is the dolphin.', 'Respondemos «My favorite animal is...».', 3),
  ('Junior 1', 'L12', 'Lesson 12 · All About Me & My Family', 'Presentación personal completa y miembros de la familia', '🌟', 'multiple_choice', 'I ___ pizza and ice cream, but I don''t like broccoli.', '["like", "likes", "am like", "liking"]'::jsonb, 'like', 'Con «I» usamos «I like...» (Me gusta) y «I don''t like...» (No me gusta).', 4),
  ('Teens 1', 'L1', 'Lesson 1 · The English Alphabet, Spelling & Professions', 'Abecedario, deletreo, ocupaciones y frases de clase', '🔤', 'multiple_choice', 'How many letters and vowels are there in the English alphabet?', '["26 letters and 5 vowels", "27 letters and 5 vowels", "26 letters and 6 vowels", "24 letters and 5 vowels"]'::jsonb, '26 letters and 5 vowels', 'El abecedario en inglés tiene 26 letras en total y 5 vocales (A, E, I, O, U).', 1),
  ('Teens 1', 'L1', 'Lesson 1 · The English Alphabet, Spelling & Professions', 'Abecedario, deletreo, ocupaciones y frases de clase', '🔤', 'multiple_choice', 'A: ___ do you spell your last name? — B: R - O - J - A - S.', '["How", "What", "Where", "Who"]'::jsonb, 'How', 'Para preguntar cómo se deletrea una palabra o nombre usamos siempre: «How do you spell...?».', 2),
  ('Teens 1', 'L1', 'Lesson 1 · The English Alphabet, Spelling & Professions', 'Abecedario, deletreo, ocupaciones y frases de clase', '🔤', 'multiple_choice', 'In emails and usernames, how do we say the symbols «@» and «_» in English?', '["at / underscore", "in / dash", "at / point", "around / line"]'::jsonb, 'at / underscore', 'En usuarios y correos electrónicos, «@» se dice «at», «.» se dice «dot» y «_» se dice «underscore».', 3),
  ('Teens 1', 'L1', 'Lesson 1 · The English Alphabet, Spelling & Professions', 'Abecedario, deletreo, ocupaciones y frases de clase', '🔤', 'multiple_choice', 'My sister works in a hospital and helps sick patients. She is a ___.', '["nurse", "lawyer", "architect", "accountant"]'::jsonb, 'nurse', '«Nurse» significa enfermera/o; «lawyer» es abogado/a y «accountant» es contador/a.', 4),
  ('Teens 1', 'L1', 'Lesson 1 · The English Alphabet, Spelling & Professions', 'Abecedario, deletreo, ocupaciones y frases de clase', '🔤', 'multiple_choice', 'Which classroom phrase do you use when you don''t know a word in English?', '["How do you say ___ in English?", "Where are you from?", "Nice to meet you!", "See you tomorrow!"]'::jsonb, 'How do you say ___ in English?', '«How do you say ___ in English?» es la frase clave del salón para preguntar vocabulario nuevo.', 5),
  ('Teens 1', 'L2', 'Lesson 2 · Personal Pronouns, Verb To Be, Family & Articles', 'Am / is / are, artículos a/an/the, países y familia', '👨‍👩‍👧‍👦', 'multiple_choice', 'Carlos and I ___ from Venezuela. We ___ students at Living English.', '["are / are", "am / are", "is / are", "are / is"]'::jsonb, 'are / are', '«Carlos and I» equivale al pronombre «We» (nosotros), que siempre usa la forma «are» del verbo To Be.', 1),
  ('Teens 1', 'L2', 'Lesson 2 · Personal Pronouns, Verb To Be, Family & Articles', 'Am / is / are, artículos a/an/the, países y familia', '👨‍👩‍👧‍👦', 'multiple_choice', 'My uncle is ___ engineer and my aunt is ___ teacher.', '["an / a", "a / an", "a / a", "an / an"]'::jsonb, 'an / a', 'Usamos «an» antes de sonido vocálico (an engineer) y «a» antes de sonido consonántico (a teacher).', 2),
  ('Teens 1', 'L2', 'Lesson 2 · Personal Pronouns, Verb To Be, Family & Articles', 'Am / is / are, artículos a/an/the, países y familia', '👨‍👩‍👧‍👦', 'multiple_choice', 'A: ___ your sister a doctor? — B: No, she ___. She is a lawyer.', '["Is / isn''t", "Are / aren''t", "Am / not", "Does / doesn''t"]'::jsonb, 'Is / isn''t', 'Para tercera persona singular (she/he/it) preguntamos con «Is...?» y negamos con «isn''t».', 3),
  ('Teens 1', 'L2', 'Lesson 2 · Personal Pronouns, Verb To Be, Family & Articles', 'Am / is / are, artículos a/an/the, países y familia', '👨‍👩‍👧‍👦', 'multiple_choice', 'My mother''s brother is my ___, and his daughter is my ___.', '["uncle / cousin", "grandfather / niece", "nephew / aunt", "brother / sister"]'::jsonb, 'uncle / cousin', 'El hermano de mi mamá es mi tío («uncle») y su hija es mi prima («cousin»).', 4),
  ('Teens 1', 'L2', 'Lesson 2 · Personal Pronouns, Verb To Be, Family & Articles', 'Am / is / are, artículos a/an/the, países y familia', '👨‍👩‍👧‍👦', 'multiple_choice', 'Choose the correct order for physical description in English:', '["She has long brown hair.", "She has hair brown long.", "She is long hair brown.", "She has brown hair long."]'::jsonb, 'She has long brown hair.', 'En inglés los adjetivos van ANTES del sustantivo (tamaño + color + sustantivo: long brown hair).', 5),
  ('Teens 1', 'L3', 'Lesson 3 · Plural Nouns, Food, Some / Any & Demonstratives', 'Plurales regulares e irregulares, some/any, how much/many, this/that/these/those', '🍎', 'multiple_choice', 'What is the correct plural form of: «child», «tooth», and «woman»?', '["children, teeth, women", "childs, tooths, womans", "childrens, teeths, women", "children, tooths, womens"]'::jsonb, 'children, teeth, women', 'Son plurales irregulares: child → children, tooth → teeth, woman → women.', 1),
  ('Teens 1', 'L3', 'Lesson 3 · Plural Nouns, Food, Some / Any & Demonstratives', 'Plurales regulares e irregulares, some/any, how much/many, this/that/these/those', '🍎', 'multiple_choice', 'There isn''t ___ milk in the fridge, but there are ___ apples on the table.', '["any / some", "some / any", "many / much", "a / an"]'::jsonb, 'any / some', 'Usamos «any» en oraciones negativas e interrogativas, y «some» en oraciones afirmativas.', 2),
  ('Teens 1', 'L3', 'Lesson 3 · Plural Nouns, Food, Some / Any & Demonstratives', 'Plurales regulares e irregulares, some/any, how much/many, this/that/these/those', '🍎', 'multiple_choice', '___ sugar do you want in your coffee, and ___ oranges do we need?', '["How much / how many", "How many / how much", "How much / how much", "Some / any"]'::jsonb, 'How much / how many', '«How much» se usa con incontables (sugar, water, money) y «How many» con contables en plural (oranges).', 3),
  ('Teens 1', 'L3', 'Lesson 3 · Plural Nouns, Food, Some / Any & Demonstratives', 'Plurales regulares e irregulares, some/any, how much/many, this/that/these/those', '🍎', 'multiple_choice', 'Look at ___ birds up in the sky! And look at ___ book in my hand.', '["those / this", "these / that", "this / those", "that / these"]'::jsonb, 'those / this', '«Those» es para plural lejos (birds in the sky) y «this» es para singular cerca (in my hand).', 4),
  ('Teens 1', 'L3', 'Lesson 3 · Plural Nouns, Food, Some / Any & Demonstratives', 'Plurales regulares e irregulares, some/any, how much/many, this/that/these/those', '🍎', 'multiple_choice', 'What is the plural of «city» and «box»?', '["cities / boxes", "citys / boxs", "cities / boxies", "cityes / boxes"]'::jsonb, 'cities / boxes', 'Consonante + y cambia a «-ies» (cities); palabras terminadas en -s, -sh, -ch, -x agregan «-es» (boxes).', 5),
  ('Teens 1', 'L4', 'Lesson 4 · Simple Present (Do / Does) & Question Words', 'Rutinas en presente simple, tercera persona (-s/-es), do vs. make', '⚡', 'multiple_choice', 'Sofía ___ English every afternoon, and her brothers ___ soccer.', '["studies / play", "study / plays", "studies / plays", "studys / play"]'::jsonb, 'studies / play', 'En 3ra persona singular (Sofía = she) «study» pasa a «studies». En plural (her brothers = they) el verbo va en forma base «play».', 1),
  ('Teens 1', 'L4', 'Lesson 4 · Simple Present (Do / Does) & Question Words', 'Rutinas en presente simple, tercera persona (-s/-es), do vs. make', '⚡', 'multiple_choice', 'A: ___ your father work on Saturdays? — B: No, he ___.', '["Does / doesn''t", "Do / don''t", "Is / isn''t", "Does / don''t"]'::jsonb, 'Does / doesn''t', 'Con he/she/it usamos el auxiliar «Does» para preguntar y «doesn''t» para responder en negativo.', 2),
  ('Teens 1', 'L4', 'Lesson 4 · Simple Present (Do / Does) & Question Words', 'Rutinas en presente simple, tercera persona (-s/-es), do vs. make', '⚡', 'multiple_choice', 'Every morning I ___ my bed, and at night I ___ my English homework.', '["make / do", "do / make", "make / make", "do / do"]'::jsonb, 'make / do', 'Decimos «make the bed / make breakfast / make a mistake» pero «do homework / do exercises / do housework».', 3),
  ('Teens 1', 'L4', 'Lesson 4 · Simple Present (Do / Does) & Question Words', 'Rutinas en presente simple, tercera persona (-s/-es), do vs. make', '⚡', 'multiple_choice', '___ do you usually have lunch with? — With my coworkers.', '["Who", "Where", "When", "Why"]'::jsonb, 'Who', '«Who ... with?» pregunta «¿Con quién...?» (preposición al final de la pregunta).', 4),
  ('Teens 1', 'L4', 'Lesson 4 · Simple Present (Do / Does) & Question Words', 'Rutinas en presente simple, tercera persona (-s/-es), do vs. make', '⚡', 'multiple_choice', 'She doesn''t ___ coffee at night because she wants to sleep well.', '["drink", "drinks", "drinking", "to drink"]'::jsonb, 'drink', 'Después de «doesn''t» o «don''t», el verbo principal va SIEMPRE en su forma base sin «-s» (drink).', 5),
  ('Teens 1', 'L4B', 'Lesson 4B · Present Continuous vs. Simple Present', 'Acciones ahora mismo (am/is/are + -ing) vs. hábitos y rutinas', '🎬', 'multiple_choice', 'Look! It ___ outside right now. Take your umbrella!', '["is raining", "rains", "rain", "are raining"]'::jsonb, 'is raining', 'Para algo que está ocurriendo en este preciso momento («Look! / right now») usamos Present Continuous (is + -ing).', 1),
  ('Teens 1', 'L4B', 'Lesson 4B · Present Continuous vs. Simple Present', 'Acciones ahora mismo (am/is/are + -ing) vs. hábitos y rutinas', '🎬', 'multiple_choice', 'My mom usually ___ dinner, but tonight my dad ___ pizza.', '["cooks / is making", "is cooking / makes", "cook / is making", "cooks / makes"]'::jsonb, 'cooks / is making', '«Usually» indica hábito (Simple Present: cooks) y «tonight / right now» indica acción temporal en progreso (is making).', 2),
  ('Teens 1', 'L4B', 'Lesson 4B · Present Continuous vs. Simple Present', 'Acciones ahora mismo (am/is/are + -ing) vs. hábitos y rutinas', '🎬', 'multiple_choice', 'What is the correct -ing spelling of «swim», «write», and «run»?', '["swimming, writing, running", "swiming, writeing, runing", "swimming, writting, running", "swiming, writing, running"]'::jsonb, 'swimming, writing, running', 'Verbos cortos CVC duplican la última consonante (swimming, running); verbos terminados en -e muda la eliminan (writing).', 3),
  ('Teens 1', 'L4B', 'Lesson 4B · Present Continuous vs. Simple Present', 'Acciones ahora mismo (am/is/are + -ing) vs. hábitos y rutinas', '🎬', 'multiple_choice', 'A: What ___ the children doing? — B: They ___ playing in the yard.', '["are / are", "do / are", "is / are", "are / do"]'::jsonb, 'are / are', '«The children» es plural (they), por lo que usa «are» tanto en la pregunta como en la respuesta.', 4),
  ('Teens 1', 'L4B', 'Lesson 4B · Present Continuous vs. Simple Present', 'Acciones ahora mismo (am/is/are + -ing) vs. hábitos y rutinas', '🎬', 'multiple_choice', 'I ___ English every week, and right now I ___ a practice exercise.', '["study / am doing", "am studying / do", "studies / am doing", "study / do"]'::jsonb, 'study / am doing', '«Every week» = rutina (study); «right now» = en progreso ahora mismo (am doing).', 5),
  ('Teens 1', 'L5', 'Lesson 5 · Numbers, Dates, Years & Telling the Time', 'Números ordinales, fechas, años, meses y cómo decir la hora', '⏰', 'multiple_choice', 'How do you write and say the ordinal numbers 1st, 2nd, and 3rd?', '["first, second, third", "oneth, twoth, threeth", "first, twosecond, third", "one, two, three"]'::jsonb, 'first, second, third', 'Para fechas y posiciones usamos números ordinales: 1st = first, 2nd = second, 3rd = third, 4th = fourth.', 1),
  ('Teens 1', 'L5', 'Lesson 5 · Numbers, Dates, Years & Telling the Time', 'Números ordinales, fechas, años, meses y cómo decir la hora', '⏰', 'multiple_choice', 'It''s 7:45. What is another natural way to say this time in English?', '["It''s a quarter to eight.", "It''s a quarter past seven.", "It''s half past seven.", "It''s fifteen to seven."]'::jsonb, 'It''s a quarter to eight.', '7:45 = faltan 15 minutos (un cuarto) para las ocho: «It''s a quarter to eight».', 2),
  ('Teens 1', 'L5', 'Lesson 5 · Numbers, Dates, Years & Telling the Time', 'Números ordinales, fechas, años, meses y cómo decir la hora', '⏰', 'multiple_choice', 'It''s 3:30. How do we say this time?', '["It''s half past three.", "It''s a quarter to three.", "It''s thirty to four.", "It''s half to three."]'::jsonb, 'It''s half past three.', 'Las y media se expresan con «half past + hora»: 3:30 = It''s half past three (o three thirty).', 3),
  ('Teens 1', 'L5', 'Lesson 5 · Numbers, Dates, Years & Telling the Time', 'Números ordinales, fechas, años, meses y cómo decir la hora', '⏰', 'multiple_choice', 'How do we read the year «1998» and «2027» in English?', '["nineteen ninety-eight / twenty twenty-seven", "one九nine-eight / two twenty-seven", "nineteen hundred eight / two thousand seven", "ninety-eight / twenty-seven"]'::jsonb, 'nineteen ninety-eight / twenty twenty-seven', 'Los años de 4 cifras suelen dividirse en dos pares de números: 19-98 (nineteen ninety-eight) y 20-27 (twenty twenty-seven).', 4),
  ('Teens 1', 'L5', 'Lesson 5 · Numbers, Dates, Years & Telling the Time', 'Números ordinales, fechas, años, meses y cómo decir la hora', '⏰', 'multiple_choice', 'What time ___ you wake up on Mondays? — I wake up ___ 6:30 am.', '["do / at", "are / on", "does / in", "do / in"]'::jsonb, 'do / at', 'Para horas exactas del reloj usamos siempre la preposición «at» (at 6:30 am).', 5),
  ('Teens 1', 'L6', 'Lesson 6 · Prepositions of Time & Place + Directions', 'Uso de IN / ON / AT, lugares de la ciudad y cómo dar direcciones', '🗺️', 'multiple_choice', 'My birthday is ___ July, ___ July 15th, and the party starts ___ 8:00 pm.', '["in / on / at", "on / in / at", "in / at / on", "at / on / in"]'::jsonb, 'in / on / at', 'Regla de oro: IN para meses y años (in July), ON para días y fechas específicas (on July 15th) y AT para horas (at 8:00 pm).', 1),
  ('Teens 1', 'L6', 'Lesson 6 · Prepositions of Time & Place + Directions', 'Uso de IN / ON / AT, lugares de la ciudad y cómo dar direcciones', '🗺️', 'multiple_choice', 'The pharmacy is ___ the bank and the bakery.', '["between", "among", "in", "under"]'::jsonb, 'between', '«Between» significa «entre dos lugares específicos» (between the bank and the bakery).', 2),
  ('Teens 1', 'L6', 'Lesson 6 · Prepositions of Time & Place + Directions', 'Uso de IN / ON / AT, lugares de la ciudad y cómo dar direcciones', '🗺️', 'multiple_choice', 'Excuse me, how can I get to the museum? — Go ___ ahead for two blocks and ___ left.', '["straight / turn", "direct / go", "front / make", "up / walk"]'::jsonb, 'straight / turn', 'Para dar direcciones usamos «Go straight ahead» (sigue derecho) y «turn left / turn right» (cruza a la izquierda/derecha).', 3),
  ('Teens 1', 'L6', 'Lesson 6 · Prepositions of Time & Place + Directions', 'Uso de IN / ON / AT, lugares de la ciudad y cómo dar direcciones', '🗺️', 'multiple_choice', 'The bus stop is right ___ of the hospital, on the other side of the street.', '["across from", "inside", "under", "between"]'::jsonb, 'across from', '«Across from» (o «in front of / opposite») indica que está cruzando la calle, frente al otro lugar.', 4),
  ('Teens 1', 'L6', 'Lesson 6 · Prepositions of Time & Place + Directions', 'Uso de IN / ON / AT, lugares de la ciudad y cómo dar direcciones', '🗺️', 'multiple_choice', 'We never have classes ___ Sundays, but we study ___ the morning.', '["on / in", "in / on", "at / in", "on / at"]'::jsonb, 'on / in', 'Usamos «on» con los días de la semana (on Sundays) e «in» con las partes del día (in the morning / afternoon / evening).', 5),
  ('Teens 1', 'L7', 'Lesson 7 · Past of Verb To Be: Was / Were', 'Pasado del verbo To Be (was, were, wasn''t, weren''t) y expresiones de pasado', '⏳', 'multiple_choice', 'Where ___ you yesterday evening? — I ___ at the cinema with my friends.', '["were / was", "was / were", "were / were", "did / was"]'::jsonb, 'were / was', 'Con «you/we/they» usamos «were», y con «I/he/she/it» usamos «was».', 1),
  ('Teens 1', 'L7', 'Lesson 7 · Past of Verb To Be: Was / Were', 'Pasado del verbo To Be (was, were, wasn''t, weren''t) y expresiones de pasado', '⏳', 'multiple_choice', 'The weather ___ cold last weekend; it ___ sunny and warm!', '["wasn''t / was", "weren''t / were", "didn''t / was", "isn''t / is"]'::jsonb, 'wasn''t / was', '«The weather» (it) es singular, por lo que en pasado usa «wasn''t» y «was».', 2),
  ('Teens 1', 'L7', 'Lesson 7 · Past of Verb To Be: Was / Were', 'Pasado del verbo To Be (was, were, wasn''t, weren''t) y expresiones de pasado', '⏳', 'multiple_choice', 'A: ___ they tired after the soccer match? — B: Yes, they ___.', '["Were / were", "Was / was", "Did / did", "Are / are"]'::jsonb, 'Were / were', 'Con «they» preguntamos «Were they...?» y respondemos «Yes, they were.»', 3),
  ('Teens 1', 'L7', 'Lesson 7 · Past of Verb To Be: Was / Were', 'Pasado del verbo To Be (was, were, wasn''t, weren''t) y expresiones de pasado', '⏳', 'multiple_choice', 'When ___ your brother born? — He ___ born in 2010.', '["was / was", "were / was", "did / is", "is / was"]'::jsonb, 'was / was', 'En inglés «nacer» se expresa en pasado pasivo con To Be: «He was born in...».', 4),
  ('Teens 1', 'L7', 'Lesson 7 · Past of Verb To Be: Was / Were', 'Pasado del verbo To Be (was, were, wasn''t, weren''t) y expresiones de pasado', '⏳', 'multiple_choice', 'Which time expression is used with the Past Tense (was / were)?', '["two days ago", "next week", "tomorrow morning", "right now"]'::jsonb, 'two days ago', '«Ago» (two days ago = hace dos días), «yesterday» y «last night» indican tiempo pasado.', 5),
  ('Teens 1', 'L8', 'Lesson 8 · Simple Future: Will & Be Going To', 'Futuro con Will / Won''t y planes con Am/Is/Are Going To', '🚀', 'multiple_choice', 'Look at those dark clouds! It ___ rain in a few minutes.', '["is going to", "will be", "going to", "wills"]'::jsonb, 'is going to', 'Usamos «be going to» para planes ya decididos o predicciones con evidencia visible ahora mismo (nubes oscuras).', 1),
  ('Teens 1', 'L8', 'Lesson 8 · Simple Future: Will & Be Going To', 'Futuro con Will / Won''t y planes con Am/Is/Are Going To', '🚀', 'multiple_choice', 'Don''t worry about the heavy bag. I ___ help you carry it!', '["will", "am going", "going to", "did"]'::jsonb, 'will', 'Usamos «will» para decisiones espontáneas tomadas en el momento de hablar, promesas y ofrecimientos.', 2),
  ('Teens 1', 'L8', 'Lesson 8 · Simple Future: Will & Be Going To', 'Futuro con Will / Won''t y planes con Am/Is/Are Going To', '🚀', 'multiple_choice', 'What is the negative contraction of «will not»?', '["won''t", "willn''t", "don''t will", "not will"]'::jsonb, 'won''t', 'La forma negativa contraída de «will not» es «won''t» (She won''t arrive late).', 3),
  ('Teens 1', 'L8', 'Lesson 8 · Simple Future: Will & Be Going To', 'Futuro con Will / Won''t y planes con Am/Is/Are Going To', '🚀', 'multiple_choice', 'Next year we ___ travel to Madrid to visit our cousins.', '["are going to", "going to", "will to", "is going to"]'::jsonb, 'are going to', 'La estructura completa requiere el verbo To Be antes de «going to»: We + are going to + verbo.', 4),
  ('Teens 1', 'L8', 'Lesson 8 · Simple Future: Will & Be Going To', 'Futuro con Will / Won''t y planes con Am/Is/Are Going To', '🚀', 'multiple_choice', 'A: ___ she be at the meeting tomorrow? — B: Yes, she ___.', '["Will / will", "Is / will", "Does / will", "Will / is"]'::jsonb, 'Will / will', 'Las preguntas con «Will» se responden de forma corta con «Yes, she will / No, she won''t».', 5),
  ('Teens 2', 'Review', 'Review · The 4 Simple Tenses & Phrases to Gain Time', 'Repaso de To Be, Do/Does, Was/Were, Will y muletillas conversacionales', '🔄', 'multiple_choice', '___ your mother cook arepas on weekends? — Yes, she ___.', '["Does / does", "Is / is", "Do / do", "Did / does"]'::jsonb, 'Does / does', 'Con un verbo de acción («cook») en presente simple y 3ra persona singular usamos el auxiliar «Does».', 1),
  ('Teens 2', 'Review', 'Review · The 4 Simple Tenses & Phrases to Gain Time', 'Repaso de To Be, Do/Does, Was/Were, Will y muletillas conversacionales', '🔄', 'multiple_choice', 'They ___ at home last night because they went to a concert.', '["weren''t", "didn''t", "don''t", "wasn''t"]'::jsonb, 'weren''t', 'Para estar en un lugar en pasado («at home last night») con «they» usamos «weren''t».', 2),
  ('Teens 2', 'Review', 'Review · The 4 Simple Tenses & Phrases to Gain Time', 'Repaso de To Be, Do/Does, Was/Were, Will y muletillas conversacionales', '🔄', 'multiple_choice', 'Which phrase is best to gain time while thinking in a conversation without staying silent?', '["Well... let me think...", "Goodbye, see you!", "I don''t speak.", "Repeat the test."]'::jsonb, 'Well... let me think...', 'Frases como «Well... let me think...» o «What I mean is...» te dan tiempo para pensar manteniendo la fluidez.', 3),
  ('Teens 2', 'Review', 'Review · The 4 Simple Tenses & Phrases to Gain Time', 'Repaso de To Be, Do/Does, Was/Were, Will y muletillas conversacionales', '🔄', 'multiple_choice', 'We ___ travel next month because we have exams at the university.', '["won''t", "weren''t", "doesn''t", "aren''t"]'::jsonb, 'won''t', 'Para negar una acción futura («next month») con «will» usamos «won''t» + verbo base.', 4),
  ('Teens 2', 'Review', 'Review · The 4 Simple Tenses & Phrases to Gain Time', 'Repaso de To Be, Do/Does, Was/Were, Will y muletillas conversacionales', '🔄', 'multiple_choice', 'Transform into a negative sentence: «He lives in Maracay.»', '["He doesn''t live in Maracay.", "He don''t live in Maracay.", "He isn''t live in Maracay.", "He doesn''t lives in Maracay."]'::jsonb, 'He doesn''t live in Maracay.', 'En negativo de 3ra persona usamos «doesn''t» y el verbo vuelve a su forma base sin -s («live»).', 5),
  ('Teens 2', 'L1', 'Lesson 1 · Pronouns, There + To Be, Both/Either/Neither & Connectors', 'Pronombres reflexivos e indefinidos, there was/will be, hogar, cine y recetas', '🏠', 'multiple_choice', 'Be careful with that knife! You might cut ___.', '["yourself", "himself", "myself", "yourselves"]'::jsonb, 'yourself', 'El pronombre reflexivo para «you» (singular) es «yourself».', 1),
  ('Teens 2', 'L1', 'Lesson 1 · Pronouns, There + To Be, Both/Either/Neither & Connectors', 'Pronombres reflexivos e indefinidos, there was/will be, hogar, cine y recetas', '🏠', 'multiple_choice', 'In my future house, ___ a big swimming pool and three bedrooms.', '["there will be", "there is", "there were", "will have"]'::jsonb, 'there will be', '«Habrá» en futuro se dice «there will be» (tanto para singular como para plural).', 2),
  ('Teens 2', 'L1', 'Lesson 1 · Pronouns, There + To Be, Both/Either/Neither & Connectors', 'Pronombres reflexivos e indefinidos, there was/will be, hogar, cine y recetas', '🏠', 'multiple_choice', 'I knocked on the door, but ___ answered. The house was empty.', '["nobody", "anybody", "somebody", "everybody"]'::jsonb, 'nobody', 'Con verbo en afirmativo («answered»), «nobody / no one» expresa ausencia total («nadie respondió»).', 3),
  ('Teens 2', 'L1', 'Lesson 1 · Pronouns, There + To Be, Both/Either/Neither & Connectors', 'Pronombres reflexivos e indefinidos, there was/will be, hogar, cine y recetas', '🏠', 'multiple_choice', '___ coffee and tea have caffeine, so I don''t drink ___ of them at night.', '["Both / either", "Either / neither", "Neither / both", "Both / neither"]'::jsonb, 'Both / either', '«Both A and B» = ambos; después de un verbo negativo («don''t drink») usamos «either» (ninguno de los dos).', 4),
  ('Teens 2', 'L1', 'Lesson 1 · Pronouns, There + To Be, Both/Either/Neither & Connectors', 'Pronombres reflexivos e indefinidos, there was/will be, hogar, cine y recetas', '🏠', 'multiple_choice', 'Which sequence of connectors is best to explain a recipe step by step?', '["First, then, after that, finally", "Because, although, however, so", "Yesterday, ago, last, never", "Who, which, whose, where"]'::jsonb, 'First, then, after that, finally', 'Para ordenar pasos de una receta o historia usamos conectores de secuencia: First, then, next, after that, finally.', 5),
  ('Teens 2', 'L2', 'Lesson 2 · Simple Past: Regular & Irregular Verbs + DID', 'Verbos regulares (-ed), irregulares y preguntas/negaciones con DID', '✈️', 'multiple_choice', 'Last summer we ___ to Mérida and ___ lots of photos in the mountains.', '["went / took", "go / take", "went / taked", "goed / took"]'::jsonb, 'went / took', 'Ambos son verbos irregulares en pasado: go → went, take → took.', 1),
  ('Teens 2', 'L2', 'Lesson 2 · Simple Past: Regular & Irregular Verbs + DID', 'Verbos regulares (-ed), irregulares y preguntas/negaciones con DID', '✈️', 'multiple_choice', 'A: Where ___ you go on your last vacation? — B: I ___ to Margarita Island.', '["did / went", "did / go", "were / went", "do / went"]'::jsonb, 'did / went', 'En la pregunta con «did» el verbo va en base («did you go»), pero en la respuesta afirmativa va en pasado («I went»).', 2),
  ('Teens 2', 'L2', 'Lesson 2 · Simple Past: Regular & Irregular Verbs + DID', 'Verbos regulares (-ed), irregulares y preguntas/negaciones con DID', '✈️', 'multiple_choice', 'She ___ the movie last night because she ___ too tired.', '["didn''t watch / was", "didn''t watched / was", "wasn''t watch / did", "don''t watch / were"]'::jsonb, 'didn''t watch / was', 'Con «didn''t» el verbo queda en base («didn''t watch»); el verbo To Be no usa did sino «was/were».', 3),
  ('Teens 2', 'L2', 'Lesson 2 · Simple Past: Regular & Irregular Verbs + DID', 'Verbos regulares (-ed), irregulares y preguntas/negaciones con DID', '✈️', 'multiple_choice', 'What is the Simple Past of «buy», «see», and «write»?', '["bought, saw, wrote", "buyed, seed, writed", "bought, seen, written", "brought, saw, wrote"]'::jsonb, 'bought, saw, wrote', 'Pasado simple irregular: buy → bought, see → saw, write → wrote.', 4),
  ('Teens 2', 'L2', 'Lesson 2 · Simple Past: Regular & Irregular Verbs + DID', 'Verbos regulares (-ed), irregulares y preguntas/negaciones con DID', '✈️', 'multiple_choice', 'How is the -ed ending pronounced in «wanted» and «needed»?', '["/ɪd/ (extra syllable)", "/t/", "/d/", "silent"]'::jsonb, '/ɪd/ (extra syllable)', 'Cuando el verbo termina en sonido /t/ o /d/ (want, need, decide), la terminación «-ed» se pronuncia /ɪd/.', 5),
  ('Teens 2', 'L3', 'Lesson 3 · Possessive Adjectives & Possessive Pronouns', 'My vs. mine, your vs. yours, her vs. hers, their vs. theirs, Whose...?', '🔑', 'multiple_choice', 'This is not ___ umbrella. ___ is blue, and this one is black.', '["my / Mine", "mine / My", "my / My", "me / Mine"]'::jsonb, 'my / Mine', '«My» es adjetivo posesivo (va antes del sustantivo: my umbrella); «Mine» es pronombre posesivo (reemplaza al sustantivo).', 1),
  ('Teens 2', 'L3', 'Lesson 3 · Possessive Adjectives & Possessive Pronouns', 'My vs. mine, your vs. yours, her vs. hers, their vs. theirs, Whose...?', '🔑', 'multiple_choice', 'A: ___ notebook is this on the desk? — B: It''s ___ (belonging to María).', '["Whose / hers", "Who''s / her", "Whose / her", "Who / hers"]'::jsonb, 'Whose / hers', '«Whose» pregunta «¿De quién?» y «hers» significa «el/la de ella» sin repetir el sustantivo.', 2),
  ('Teens 2', 'L3', 'Lesson 3 · Possessive Adjectives & Possessive Pronouns', 'My vs. mine, your vs. yours, her vs. hers, their vs. theirs, Whose...?', '🔑', 'multiple_choice', 'We love ___ academy, and the students in the other classroom love ___ too.', '["our / theirs", "ours / their", "our / their", "ours / theirs"]'::jsonb, 'our / theirs', '«Our» acompaña a «academy»; «theirs» va solo al final significando «la de ellos».', 3),
  ('Teens 2', 'L3', 'Lesson 3 · Possessive Adjectives & Possessive Pronouns', 'My vs. mine, your vs. yours, her vs. hers, their vs. theirs, Whose...?', '🔑', 'multiple_choice', 'Is that car ___? — Yes, they bought it last week.', '["theirs", "their", "them", "they''re"]'::jsonb, 'theirs', 'Como no sigue ningún sustantivo después, usamos el pronombre posesivo «theirs».', 4),
  ('Teens 2', 'L3', 'Lesson 3 · Possessive Adjectives & Possessive Pronouns', 'My vs. mine, your vs. yours, her vs. hers, their vs. theirs, Whose...?', '🔑', 'multiple_choice', 'The dog wagged ___ tail happily when it saw ___ owner.', '["its / its", "it''s / its", "its / it''s", "his / it''s"]'::jsonb, 'its / its', '«Its» (sin apóstrofo) es el posesivo de cosas o animales; «it''s» con apóstrofo significa «it is».', 5),
  ('Teens 2', 'L4', 'Lesson 4 · Past Habits: Used To vs. Be Used To', 'Hábitos del pasado (used to + verbo) vs. estar acostumbrado a (be used to + -ing)', '🚲', 'multiple_choice', 'When I was a child, I ___ play video games all afternoon, but now I''m busy.', '["used to", "use to", "am used to", "was used to"]'::jsonb, 'used to', '«Used to + verbo base» expresa un hábito o estado en el pasado que ya no ocurre en el presente.', 1),
  ('Teens 2', 'L4', 'Lesson 4 · Past Habits: Used To vs. Be Used To', 'Hábitos del pasado (used to + verbo) vs. estar acostumbrado a (be used to + -ing)', '🚲', 'multiple_choice', 'She ___ like coffee before, but now she drinks two cups every morning.', '["didn''t use to", "didn''t used to", "wasn''t use to", "not used to"]'::jsonb, 'didn''t use to', 'En negativo e interrogativo con «did/didn''t», «used to» pierde la «d» y se escribe «use to».', 2),
  ('Teens 2', 'L4', 'Lesson 4 · Past Habits: Used To vs. Be Used To', 'Hábitos del pasado (used to + verbo) vs. estar acostumbrado a (be used to + -ing)', '🚲', 'multiple_choice', 'I live in a big city now, so I ___ the heavy traffic and noise.', '["am used to", "used to", "use to", "did use to"]'::jsonb, 'am used to', '«Be used to + sustantivo o verbo -ing» significa «estar acostumbrado a algo» en el presente.', 3),
  ('Teens 2', 'L4', 'Lesson 4 · Past Habits: Used To vs. Be Used To', 'Hábitos del pasado (used to + verbo) vs. estar acostumbrado a (be used to + -ing)', '🚲', 'multiple_choice', 'Doctors are used to ___ long hours at the hospital.', '["working", "work", "worked", "works"]'::jsonb, 'working', 'Después de «be used to» o «get used to», el verbo lleva siempre «-ing» porque «to» aquí es preposición.', 4),
  ('Teens 2', 'L4', 'Lesson 4 · Past Habits: Used To vs. Be Used To', 'Hábitos del pasado (used to + verbo) vs. estar acostumbrado a (be used to + -ing)', '🚲', 'multiple_choice', '___ you ___ live in Valencia before moving to Caracas?', '["Did / use to", "Did / used to", "Were / use to", "Are / used to"]'::jsonb, 'Did / use to', 'Pregunta sobre hábito pasado: «Did + sujeto + use to + verbo base?».', 5),
  ('Teens 2', 'L5', 'Lesson 5 · Adjectives -ED vs. -ING & Adjective Order', 'Diferencia entre adjetivos con -ed y -ing y orden correcto de los adjetivos', '🎭', 'multiple_choice', 'The lecture was really ___, so many students felt ___ and sleepy.', '["boring / bored", "bored / boring", "boring / boring", "bored / bored"]'::jsonb, 'boring / bored', 'Los adjetivos con «-ing» describen lo que causa la emoción (the lecture was boring) y con «-ed» cómo se siente la persona (felt bored).', 1),
  ('Teens 2', 'L5', 'Lesson 5 · Adjectives -ED vs. -ING & Adjective Order', 'Diferencia entre adjetivos con -ed y -ing y orden correcto de los adjetivos', '🎭', 'multiple_choice', 'We are very ___ about our trip to London next month! It will be an ___ experience.', '["excited / exciting", "exciting / excited", "excited / excited", "exciting / exciting"]'::jsonb, 'excited / exciting', 'Nosotros nos sentimos «excited» (-ed); la experiencia es «exciting» (-ing).', 2),
  ('Teens 2', 'L5', 'Lesson 5 · Adjectives -ED vs. -ING & Adjective Order', 'Diferencia entre adjetivos con -ed y -ing y orden correcto de los adjetivos', '🎭', 'multiple_choice', 'Choose the correct order of adjectives (OSASCOMP):', '["a beautiful small old Italian car", "an Italian old small beautiful car", "a small beautiful Italian old car", "an old Italian beautiful small car"]'::jsonb, 'a beautiful small old Italian car', 'El orden natural en inglés es: Opinion (beautiful) → Size (small) → Age (old) → Origin (Italian) + sustantivo.', 3),
  ('Teens 2', 'L5', 'Lesson 5 · Adjectives -ED vs. -ING & Adjective Order', 'Diferencia entre adjetivos con -ed y -ing y orden correcto de los adjetivos', '🎭', 'multiple_choice', 'She bought a ___ jacket at the mall yesterday.', '["nice new black leather", "leather black new nice", "black leather nice new", "new black nice leather"]'::jsonb, 'nice new black leather', 'Orden OSASCOMP: Opinion (nice) → Age (new) → Color (black) → Material (leather).', 4),
  ('Teens 2', 'L5', 'Lesson 5 · Adjectives -ED vs. -ING & Adjective Order', 'Diferencia entre adjetivos con -ed y -ing y orden correcto de los adjetivos', '🎭', 'multiple_choice', 'That horror movie was ___! I was ___ the whole time.', '["terrifying / terrified", "terrified / terrifying", "terrify / terrifying", "terrified / terrified"]'::jsonb, 'terrifying / terrified', 'La película causa miedo («terrifying») y yo sentí miedo («terrified»).', 5),
  ('Teens 2', 'L6', 'Lesson 6 · Comparatives & Superlatives', 'Comparativos (-er / more), superlativos (-est / the most), igualdades e irregulares', '🏆', 'multiple_choice', 'A plane ticket is ___ than a bus ticket, but flying is much ___.', '["more expensive / faster", "expensiver / more fast", "most expensive / fastest", "more expensive / more fast"]'::jsonb, 'more expensive / faster', 'Adjetivos largos usan «more ... than» (more expensive); adjetivos cortos agregan «-er» (faster).', 1),
  ('Teens 2', 'L6', 'Lesson 6 · Comparatives & Superlatives', 'Comparativos (-er / more), superlativos (-est / the most), igualdades e irregulares', '🏆', 'multiple_choice', 'Angel Falls is ___ waterfall in the world!', '["the highest", "higher than", "the most high", "highest"]'::jsonb, 'the highest', 'Para el superlativo de un adjetivo corto usamos «the + adjetivo-est» (the highest).', 2),
  ('Teens 2', 'L6', 'Lesson 6 · Comparatives & Superlatives', 'Comparativos (-er / more), superlativos (-est / the most), igualdades e irregulares', '🏆', 'multiple_choice', 'What are the comparative and superlative forms of «good» and «bad»?', '["better – the best / worse – the worst", "gooder – the goodest / badder – the baddest", "more good / more bad", "better – the best / badder – the worst"]'::jsonb, 'better – the best / worse – the worst', 'Son irregulares: good → better → the best; bad → worse → the worst.', 3),
  ('Teens 2', 'L6', 'Lesson 6 · Comparatives & Superlatives', 'Comparativos (-er / more), superlativos (-est / the most), igualdades e irregulares', '🏆', 'multiple_choice', 'This laptop is just ___ fast ___ the new model, and it costs less!', '["as / as", "more / than", "so / than", "as / than"]'::jsonb, 'as / as', 'Para comparaciones de igualdad usamos «as + adjetivo + as» (tan rápido como).', 4),
  ('Teens 2', 'L6', 'Lesson 6 · Comparatives & Superlatives', 'Comparativos (-er / more), superlativos (-est / the most), igualdades e irregulares', '🏆', 'multiple_choice', 'Yesterday was ___ day of the year so far.', '["the hottest", "the hotter", "the most hot", "hotter than"]'::jsonb, 'the hottest', '«Hot» es CVC (consonante-vocal-consonante), por lo que duplica la «t» en el superlativo: «the hottest».', 5),
  ('Teens 2', 'L7', 'Lesson 7 · Adverbs of Manner & Frequency', 'Adjetivo vs. adverbio (-ly, well, fast, hard) y posición de adverbios de frecuencia', '🎯', 'multiple_choice', 'Sofía is a very ___ pianist; she plays the piano ___.', '["good / well", "well / good", "good / goodly", "good / good"]'::jsonb, 'good / well', '«Good» es adjetivo (describe a pianist) y «well» es su adverbio irregular (describe cómo toca: plays well).', 1),
  ('Teens 2', 'L7', 'Lesson 7 · Adverbs of Manner & Frequency', 'Adjetivo vs. adverbio (-ly, well, fast, hard) y posición de adverbios de frecuencia', '🎯', 'multiple_choice', 'Please drive ___! It is raining ___ tonight.', '["carefully / heavily", "careful / heavy", "carefully / heavy", "careful / heavily"]'::jsonb, 'carefully / heavily', 'Para describir cómo se realiza un verbo (drive, raining) usamos adverbios terminados en «-ly».', 2),
  ('Teens 2', 'L7', 'Lesson 7 · Adverbs of Manner & Frequency', 'Adjetivo vs. adverbio (-ly, well, fast, hard) y posición de adverbios de frecuencia', '🎯', 'multiple_choice', 'He works very ___ and runs very ___. (Be careful with irregular adverbs!)', '["hard / fast", "hardly / fastly", "hard / fastly", "hardly / fast"]'::jsonb, 'hard / fast', '«Hard» y «fast» tienen la misma forma como adjetivo y como adverbio («hardly» significa «apenas/casi no» y «fastly» no existe).', 3),
  ('Teens 2', 'L7', 'Lesson 7 · Adverbs of Manner & Frequency', 'Adjetivo vs. adverbio (-ly, well, fast, hard) y posición de adverbios de frecuencia', '🎯', 'multiple_choice', 'Choose the sentence with the correct position of the frequency adverb:', '["She is never late, and she always arrives early.", "She never is late, and she arrives always early.", "Never she is late, and always she arrives.", "She is late never, and she always arrives early."]'::jsonb, 'She is never late, and she always arrives early.', 'Los adverbios de frecuencia van DESPUÉS del verbo To Be (is never) y ANTES de los demás verbos (always arrives).', 4),
  ('Teens 2', 'L7', 'Lesson 7 · Adverbs of Manner & Frequency', 'Adjetivo vs. adverbio (-ly, well, fast, hard) y posición de adverbios de frecuencia', '🎯', 'multiple_choice', 'After verbs of perception like «look», «feel», «taste», and «smell», we use:', '["an adjective (e.g., This soup tastes great!)", "an adverb with -ly (e.g., This soup tastes greatly!)", "a noun only", "an infinitive"]'::jsonb, 'an adjective (e.g., This soup tastes great!)', 'Los verbos de los sentidos (taste, smell, look, sound, feel) van seguidos de adjetivo: «You look tired / It smells delicious».', 5),
  ('Teens 2', 'L8', 'Lesson 8 · Modal Verbs: Ability, Advice & Obligation', 'Can, could, should, must, have to, may y might', '💡', 'multiple_choice', 'You look very pale and have a fever. You ___ see a doctor today.', '["should", "can''t", "may not", "could to"]'::jsonb, 'should', 'Para dar consejos o recomendaciones («deberías») usamos «should / shouldn''t» + verbo base.', 1),
  ('Teens 2', 'L8', 'Lesson 8 · Modal Verbs: Ability, Advice & Obligation', 'Can, could, should, must, have to, may y might', '💡', 'multiple_choice', 'Passengers ___ wear a seatbelt during takeoff. It is mandatory by law.', '["must", "might", "could", "may"]'::jsonb, 'must', '«Must» y «have to» expresan obligación firme o reglas obligatorias.', 2),
  ('Teens 2', 'L8', 'Lesson 8 · Modal Verbs: Ability, Advice & Obligation', 'Can, could, should, must, have to, may y might', '💡', 'multiple_choice', 'Tomorrow is a holiday, so we ___ wake up early! It''s not necessary.', '["don''t have to", "mustn''t", "can''t", "shouldn''t to"]'::jsonb, 'don''t have to', '«Don''t have to» significa «no es necesario»; en cambio «mustn''t» significa «está prohibido».', 3),
  ('Teens 2', 'L8', 'Lesson 8 · Modal Verbs: Ability, Advice & Obligation', 'Can, could, should, must, have to, may y might', '💡', 'multiple_choice', 'When my grandfather was young, he ___ run a marathon in three hours.', '["could", "can", "may", "must"]'::jsonb, 'could', '«Could» expresa habilidad general en el pasado («podía / sabía»).', 4),
  ('Teens 2', 'L8', 'Lesson 8 · Modal Verbs: Ability, Advice & Obligation', 'Can, could, should, must, have to, may y might', '💡', 'multiple_choice', 'Take a jacket with you because it ___ get cold later tonight.', '["might", "must", "should to", "has to"]'::jsonb, 'might', '«May» y «might» expresan posibilidad futura no segura («puede que / tal vez»).', 5),
  ('Teens 3', 'L1', 'Lesson 1 · Progressive Tenses (Present, Past & Future) & Stative Verbs', 'Los 3 tiempos continuos, verbos de estado (stative verbs) y acciones interrumpidas', '⚡', 'multiple_choice', 'I ___ her phone number, and I ___ she is telling the truth. (Stative verbs!)', '["know / believe", "am knowing / am believing", "knows / believing", "knew / am believing"]'::jsonb, 'know / believe', 'Los verbos de estado mental o posesión (know, believe, own, want, need) NO llevan «-ing»; se usan en forma simple.', 1),
  ('Teens 3', 'L1', 'Lesson 1 · Progressive Tenses (Present, Past & Future) & Stative Verbs', 'Los 3 tiempos continuos, verbos de estado (stative verbs) y acciones interrumpidas', '⚡', 'multiple_choice', 'While the teacher ___ into the classroom, the students ___ loudly.', '["was walking / were talking", "walked / talked", "is walking / were talking", "will walk / talked"]'::jsonb, 'was walking / were talking', 'Dos acciones en progreso al mismo tiempo en el pasado usan Past Progressive (was/were + -ing).', 2),
  ('Teens 3', 'L1', 'Lesson 1 · Progressive Tenses (Present, Past & Future) & Stative Verbs', 'Los 3 tiempos continuos, verbos de estado (stative verbs) y acciones interrumpidas', '⚡', 'multiple_choice', 'I ___ dinner when suddenly the lights ___ out.', '["was cooking / went", "cooked / were going", "am cooking / went", "was cooking / go"]'::jsonb, 'was cooking / went', 'La acción larga de fondo va en Past Progressive (was cooking) y la acción corta que interrumpe va en Simple Past (went).', 3),
  ('Teens 3', 'L1', 'Lesson 1 · Progressive Tenses (Present, Past & Future) & Stative Verbs', 'Los 3 tiempos continuos, verbos de estado (stative verbs) y acciones interrumpidas', '⚡', 'multiple_choice', 'Don''t call me at 8:00 pm tomorrow because I ___ in the concert at that time.', '["will be singing", "am singing", "sang", "will sing"]'::jsonb, 'will be singing', 'Para una acción que estará en pleno progreso en una hora específica del futuro usamos Future Progressive (will be + -ing).', 4),
  ('Teens 3', 'L1', 'Lesson 1 · Progressive Tenses (Present, Past & Future) & Stative Verbs', 'Los 3 tiempos continuos, verbos de estado (stative verbs) y acciones interrumpidas', '⚡', 'multiple_choice', 'Why does the sentence «She is always forgetting my birthday!» use Present Progressive?', '["To express an annoying habit or complaint", "Because it is a stative verb", "To talk about the past", "Because forget is irregular"]'::jsonb, 'To express an annoying habit or complaint', '«Always + Present Progressive» se usa en nivel avanzado para expresar una queja sobre un hábito que molesta.', 5),
  ('Teens 3', 'L2', 'Lesson 2 · Perfect Tenses (Present, Past & Future)', 'Have/has + participio, had + participio, will have + participio, already/yet/since/for', '⏳', 'multiple_choice', 'We have lived in this city ___ 2018, so we have been here ___ several years.', '["since / for", "for / since", "since / since", "already / yet"]'::jsonb, 'since / for', '«Since» marca el punto de inicio en el tiempo (since 2018) y «for» marca la duración total (for several years).', 1),
  ('Teens 3', 'L2', 'Lesson 2 · Perfect Tenses (Present, Past & Future)', 'Have/has + participio, had + participio, will have + participio, already/yet/since/for', '⏳', 'multiple_choice', 'By the time we arrived at the station, the train ___ already ___.', '["had / left", "has / left", "have / leave", "will have / left"]'::jsonb, 'had / left', 'El Past Perfect («had + participio») expresa una acción que ocurrió ANTES que otra acción pasada (arrived).', 2),
  ('Teens 3', 'L2', 'Lesson 2 · Perfect Tenses (Present, Past & Future)', 'Have/has + participio, had + participio, will have + participio, already/yet/since/for', '⏳', 'multiple_choice', 'A: Have you finished the report ___? — B: Yes, I have ___ sent it to the manager.', '["yet / already", "already / yet", "since / for", "ever / never"]'::jsonb, 'yet / already', '«Yet» va al final de preguntas y negaciones; «already» va en afirmaciones entre have/has y el participio.', 3),
  ('Teens 3', 'L2', 'Lesson 2 · Perfect Tenses (Present, Past & Future)', 'Have/has + participio, had + participio, will have + participio, already/yet/since/for', '⏳', 'multiple_choice', 'By December next year, she ___ graduated from university.', '["will have", "has", "had", "would have"]'::jsonb, 'will have', '«By + fecha futura» usa Future Perfect («will have + participio») para algo que ya se habrá completado.', 4),
  ('Teens 3', 'L2', 'Lesson 2 · Perfect Tenses (Present, Past & Future)', 'Have/has + participio, had + participio, will have + participio, already/yet/since/for', '⏳', 'multiple_choice', 'What is the difference between «She has gone to Madrid» and «She has been to Madrid»?', '["''Has gone'' means she is still in Madrid; ''has been'' means she visited and returned", "They mean the exact same thing", "''Has been'' means she is still there now", "''Has gone'' is past simple"]'::jsonb, '''Has gone'' means she is still in Madrid; ''has been'' means she visited and returned', '«Has gone to» = se fue y sigue allá; «has been to» = ha ido/visitado alguna vez y ya regresó.', 5),
  ('Teens 3', 'L3', 'Lesson 3 · Countable & Uncountable Nouns, Containers & Quantifiers', 'Few vs. a few, little vs. a little, containers y sustantivos incontables avanzados', '🛒', 'multiple_choice', 'Be careful! In English, «advice», «information», «furniture», and «luggage» are:', '["Uncountable nouns (singular verb, no plural -s)", "Countable plural nouns", "Verbs", "Adjectives"]'::jsonb, 'Uncountable nouns (singular verb, no plural -s)', 'En inglés «advice, information, furniture, luggage, news, bread» son SIEMPRE incontables (decimos «a piece of advice», nunca «advices»).', 1),
  ('Teens 3', 'L3', 'Lesson 3 · Countable & Uncountable Nouns, Containers & Quantifiers', 'Few vs. a few, little vs. a little, containers y sustantivos incontables avanzados', '🛒', 'multiple_choice', 'I have ___ close friends here, so I feel happy and never lonely.', '["a few", "a little", "little", "much"]'::jsonb, 'a few', '«A few» (unos cuantos, sentido positivo) se usa con sustantivos contables en plural («friends»).', 2),
  ('Teens 3', 'L3', 'Lesson 3 · Countable & Uncountable Nouns, Containers & Quantifiers', 'Few vs. a few, little vs. a little, containers y sustantivos incontables avanzados', '🛒', 'multiple_choice', 'Hurry up! We have very ___ time left before the flight closes.', '["little", "few", "many", "a few"]'::jsonb, 'little', '«Little» (casi nada de, sentido negativo/escaso) se usa con sustantivos incontables como «time».', 3),
  ('Teens 3', 'L3', 'Lesson 3 · Countable & Uncountable Nouns, Containers & Quantifiers', 'Few vs. a few, little vs. a little, containers y sustantivos incontables avanzados', '🛒', 'multiple_choice', 'Can you buy a ___ of bread and two ___ of toothpaste at the supermarket?', '["loaf / tubes", "slice / loaves", "bar / cans", "jar / cartons"]'::jsonb, 'loaf / tubes', 'Los envases/medidas exactos son: «a loaf of bread» (una barra/pan entero) y «a tube of toothpaste» (un tubo de pasta dental).', 4),
  ('Teens 3', 'L3', 'Lesson 3 · Countable & Uncountable Nouns, Containers & Quantifiers', 'Few vs. a few, little vs. a little, containers y sustantivos incontables avanzados', '🛒', 'multiple_choice', 'How ___ pieces of luggage did you bring on the trip?', '["many", "much", "little", "amount"]'::jsonb, 'many', 'Aunque «luggage» es incontable, la palabra «pieces» es contable plural, por lo que usamos «How many pieces of...».', 5),
  ('Teens 3', 'L4', 'Lesson 4 · Conditionals: Zero, First, Second, Third & Mixed', 'Los 4 condicionales (0, 1st, 2nd, 3rd) y condicionales mixtos', '🔀', 'multiple_choice', 'First Conditional (Real future possibility): If it ___ tomorrow, we ___ the event indoors.', '["rains / will hold", "will rain / hold", "rained / would hold", "had rained / would have held"]'::jsonb, 'rains / will hold', 'En el 1er Condicional, la cláusula con «If» va en Presente Simple (rains) y el resultado va con «will + verbo».', 1),
  ('Teens 3', 'L4', 'Lesson 4 · Conditionals: Zero, First, Second, Third & Mixed', 'Los 4 condicionales (0, 1st, 2nd, 3rd) y condicionales mixtos', '🔀', 'multiple_choice', 'Second Conditional (Hypothetical present): If I ___ you, I ___ accept that job offer immediately.', '["were / would", "was / will", "am / would", "had been / would"]'::jsonb, 'were / would', 'En el 2do Condicional (hipotético) usamos «If I were you...» con «would + verbo base».', 2),
  ('Teens 3', 'L4', 'Lesson 4 · Conditionals: Zero, First, Second, Third & Mixed', 'Los 4 condicionales (0, 1st, 2nd, 3rd) y condicionales mixtos', '🔀', 'multiple_choice', 'Third Conditional (Impossible past regret): If you ___ me earlier, I ___ helped you.', '["had called / would have", "called / would have", "had called / would", "would have called / had"]'::jsonb, 'had called / would have', 'El 3er Condicional habla del pasado irreal: «If + Past Perfect (had called) → would have + participio (helped)».', 3),
  ('Teens 3', 'L4', 'Lesson 4 · Conditionals: Zero, First, Second, Third & Mixed', 'Los 4 condicionales (0, 1st, 2nd, 3rd) y condicionales mixtos', '🔀', 'multiple_choice', 'Zero Conditional (Scientific truth): If you ___ water to 100°C, it ___.', '["heat / boils", "heated / would boil", "will heat / boils", "heat / will boiled"]'::jsonb, 'heat / boils', 'Para leyes científicas y hechos universales (Zero Conditional) usamos Presente Simple en ambas partes.', 4),
  ('Teens 3', 'L4', 'Lesson 4 · Conditionals: Zero, First, Second, Third & Mixed', 'Los 4 condicionales (0, 1st, 2nd, 3rd) y condicionales mixtos', '🔀', 'multiple_choice', 'We will go to the beach ___ it rains. («a menos que»)', '["unless", "if", "as long as", "because"]'::jsonb, 'unless', '«Unless» significa «if not» (a menos que / salvo que).', 5),
  ('Teens 3', 'L5', 'Lesson 5 · Perfect Continuous Tenses', 'Present, Past & Future Perfect Continuous (have/had/will have been + -ing)', '🏃', 'multiple_choice', 'Her eyes are red because she ___ for two hours.', '["has been crying", "is crying", "cried", "had cried"]'::jsonb, 'has been crying', 'Present Perfect Continuous («has been + -ing») enfatiza la duración de una acción reciente cuya evidencia es visible ahora.', 1),
  ('Teens 3', 'L5', 'Lesson 5 · Perfect Continuous Tenses', 'Present, Past & Future Perfect Continuous (have/had/will have been + -ing)', '🏃', 'multiple_choice', 'We ___ for the bus for 40 minutes when it finally arrived.', '["had been waiting", "have been waiting", "were waiting", "will have been waiting"]'::jsonb, 'had been waiting', 'Past Perfect Continuous («had been + -ing») muestra cuánto tiempo llevaba ocurriendo algo antes de otro evento pasado (arrived).', 2),
  ('Teens 3', 'L5', 'Lesson 5 · Perfect Continuous Tenses', 'Present, Past & Future Perfect Continuous (have/had/will have been + -ing)', '🏃', 'multiple_choice', 'By next June, Professor Molina ___ at our academy for ten years.', '["will have been teaching", "has been teaching", "had been teaching", "is teaching"]'::jsonb, 'will have been teaching', 'Future Perfect Continuous («will have been + -ing») proyecta la duración acumulada de una acción hasta un momento del futuro.', 3),
  ('Teens 3', 'L5', 'Lesson 5 · Perfect Continuous Tenses', 'Present, Past & Future Perfect Continuous (have/had/will have been + -ing)', '🏃', 'multiple_choice', 'How long ___ you ___ English?', '["have / been learning", "are / learning", "did / learn", "had / learning"]'::jsonb, 'have / been learning', 'Con «How long...?» para una acción que empezó en el pasado y continúa hoy, usamos «have/has been + -ing».', 4),
  ('Teens 3', 'L5', 'Lesson 5 · Perfect Continuous Tenses', 'Present, Past & Future Perfect Continuous (have/had/will have been + -ing)', '🏃', 'multiple_choice', 'Which verb CANNOT be used in the Perfect Continuous form because it is stative?', '["know (I have known her for years)", "work (I have been working)", "study (She has been studying)", "wait (We have been waiting)"]'::jsonb, 'know (I have known her for years)', 'Los verbos de estado como «know, believe, own» nunca llevan «-ing», por lo que usan Present Perfect Simple («I have known»).', 5),
  ('Teens 3', 'L6', 'Lesson 6 · Causative & Permission: Make, Let & Be Allowed To', 'Obligar (make someone do), permitir (let someone do) y tener permiso (be allowed to)', '🚦', 'multiple_choice', 'My parents ___ me clean my room before going out with my friends.', '["made", "let to", "allowed", "forced"]'::jsonb, 'made', 'Con «make» y «let» usamos objeto + verbo base SIN «to»: «made me clean» (me obligaron/hicieron limpiar).', 1),
  ('Teens 3', 'L6', 'Lesson 6 · Causative & Permission: Make, Let & Be Allowed To', 'Obligar (make someone do), permitir (let someone do) y tener permiso (be allowed to)', '🚦', 'multiple_choice', 'Our teacher ___ us use a dictionary during the writing practice.', '["let", "allowed", "made to", "permitted"]'::jsonb, 'let', '«Let + persona + verbo sin to» expresa permiso activo («let us use»). Con «allow» sería «allowed us TO use».', 2),
  ('Teens 3', 'L6', 'Lesson 6 · Causative & Permission: Make, Let & Be Allowed To', 'Obligar (make someone do), permitir (let someone do) y tener permiso (be allowed to)', '🚦', 'multiple_choice', 'Visitors ___ take flash photographs inside the art museum.', '["are not allowed to", "don''t let to", "aren''t make to", "not allowed"]'::jsonb, 'are not allowed to', 'La estructura pasiva de permiso lleva siempre «to»: «be (not) allowed to + verbo base».', 3),
  ('Teens 3', 'L6', 'Lesson 6 · Causative & Permission: Make, Let & Be Allowed To', 'Obligar (make someone do), permitir (let someone do) y tener permiso (be allowed to)', '🚦', 'multiple_choice', 'That sad movie ___ everyone in the theater cry.', '["made", "allowed", "let to", "caused"]'::jsonb, 'made', '«Make someone + verbo base» también significa causar una reacción emocional («made everyone cry»).', 4),
  ('Teens 3', 'L6', 'Lesson 6 · Causative & Permission: Make, Let & Be Allowed To', 'Obligar (make someone do), permitir (let someone do) y tener permiso (be allowed to)', '🚦', 'multiple_choice', 'In passive voice, «The boss made him stay late» becomes: «He was made ___ late.»', '["to stay", "stay", "staying", "stayed"]'::jsonb, 'to stay', 'Importante matiz avanzado: cuando «make» pasa a voz pasiva («was made»), SÍ recupera la partícula «to» («was made to stay»).', 5),
  ('Teens 3', 'L7', 'Lesson 7 · Reported Speech (Indirect Speech)', 'Cambio de tiempos verbales (backshift), say vs. tell y preguntas reportadas', '🗣️', 'multiple_choice', 'Direct: «I am working on a project.» → Reported: She said that she ___ on a project.', '["was working", "is working", "has been working", "will be working"]'::jsonb, 'was working', 'En Reported Speech los tiempos retroceden un paso al pasado (backshift): Present Progressive (am working) → Past Progressive (was working).', 1),
  ('Teens 3', 'L7', 'Lesson 7 · Reported Speech (Indirect Speech)', 'Cambio de tiempos verbales (backshift), say vs. tell y preguntas reportadas', '🗣️', 'multiple_choice', 'Direct: «I will call you tomorrow.» → He told me that he ___ call me the next day.', '["would", "will", "can", "shall"]'::jsonb, 'would', 'Al reportar en pasado, «will» cambia a «would» y «tomorrow» cambia a «the next day / the following day».', 2),
  ('Teens 3', 'L7', 'Lesson 7 · Reported Speech (Indirect Speech)', 'Cambio de tiempos verbales (backshift), say vs. tell y preguntas reportadas', '🗣️', 'multiple_choice', 'What is the grammar difference between «say» and «tell» in Reported Speech?', '["''Tell'' requires a personal object (told me); ''say'' does not (said that...)", "''Say'' requires a personal object (said me)", "They are used identically", "''Tell'' is only for questions"]'::jsonb, '''Tell'' requires a personal object (told me); ''say'' does not (said that...)', 'Decimos «She told ME that...» (con receptor) o «She said that...» (nunca «She said me»).', 3),
  ('Teens 3', 'L7', 'Lesson 7 · Reported Speech (Indirect Speech)', 'Cambio de tiempos verbales (backshift), say vs. tell y preguntas reportadas', '🗣️', 'multiple_choice', 'Direct question: «Where do you live?» → She asked me where ___.', '["I lived", "did I live", "do I live", "lived I"]'::jsonb, 'I lived', 'Las preguntas reportadas usan el orden afirmativo (sujeto + verbo en pasado) y NO usan el auxiliar do/did: «where I lived».', 4),
  ('Teens 3', 'L7', 'Lesson 7 · Reported Speech (Indirect Speech)', 'Cambio de tiempos verbales (backshift), say vs. tell y preguntas reportadas', '🗣️', 'multiple_choice', 'Direct Yes/No question: «Are you ready?» → He asked us ___ we were ready.', '["if / whether", "that", "what", "who"]'::jsonb, 'if / whether', 'Cuando reportamos una pregunta cerrada (Yes/No), conectamos con «if» o «whether» («He asked us if we were ready»).', 5),
  ('Teens 3', 'L8', 'Lesson 8 · Passive Voice & Modals of Deduction', 'Voz pasiva en todos los tiempos y deducción lógica (must/can''t/might have + participio)', '⚖️', 'multiple_choice', 'Active: «Gabriel García Márquez wrote One Hundred Years of Solitude.» → Passive:', '["One Hundred Years of Solitude was written by G. G. Márquez.", "One Hundred Years of Solitude wrote by G. G. Márquez.", "One Hundred Years of Solitude has written by G. G. Márquez.", "One Hundred Years of Solitude is wrote by G. G. Márquez."]'::jsonb, 'One Hundred Years of Solitude was written by G. G. Márquez.', 'La voz pasiva en pasado simple se forma con «was / were + past participle» (was written by...).', 1),
  ('Teens 3', 'L8', 'Lesson 8 · Passive Voice & Modals of Deduction', 'Voz pasiva en todos los tiempos y deducción lógica (must/can''t/might have + participio)', '⚖️', 'multiple_choice', 'The new hospital ___ built right now; it will open next year.', '["is being", "is", "has been", "was"]'::jsonb, 'is being', 'En Present Continuous Passive («está siendo construido») usamos «am/is/are + being + participio».', 2),
  ('Teens 3', 'L8', 'Lesson 8 · Passive Voice & Modals of Deduction', 'Voz pasiva en todos los tiempos y deducción lógica (must/can''t/might have + participio)', '⚖️', 'multiple_choice', 'The ground is completely wet this morning. It ___ rained heavily last night!', '["must have", "can''t have", "should", "must to"]'::jsonb, 'must have', 'Para una deducción casi 100% segura sobre el pasado usamos «must have + participio».', 3),
  ('Teens 3', 'L8', 'Lesson 8 · Passive Voice & Modals of Deduction', 'Voz pasiva en todos los tiempos y deducción lógica (must/can''t/might have + participio)', '⚖️', 'multiple_choice', 'You ___ seen María at the mall yesterday because she is in Spain all month!', '["can''t have", "must have", "should have", "may have"]'::jsonb, 'can''t have', 'Para deducir que algo fue lógicamente imposible en el pasado usamos «can''t have / couldn''t have + participio».', 4),
  ('Teens 3', 'L8', 'Lesson 8 · Passive Voice & Modals of Deduction', 'Voz pasiva en todos los tiempos y deducción lógica (must/can''t/might have + participio)', '⚖️', 'multiple_choice', 'All safety protocols must ___ respected by the staff.', '["be", "been", "being", "to be"]'::jsonb, 'be', 'Con verbos modales en voz pasiva la estructura es «modal + be + past participle» (must be respected).', 5),
  ('Teens 3', 'L9', 'Lesson 9 · Phrasal Verbs in Context', 'Verbos compuestos separables e inseparables para la vida diaria y el trabajo', '🧩', 'multiple_choice', 'We need to stop at the gas station before we ___ fuel!', '["run out of", "look after", "give up", "turn off"]'::jsonb, 'run out of', '«Run out of» significa quedarse sin algo o agotarse (run out of fuel / time / money).', 1),
  ('Teens 3', 'L9', 'Lesson 9 · Phrasal Verbs in Context', 'Verbos compuestos separables e inseparables para la vida diaria y el trabajo', '🧩', 'multiple_choice', 'Never ___ on your dreams! Keep practicing every day.', '["give up", "put off", "take off", "find out"]'::jsonb, 'give up', '«Give up» significa rendirse o abandonar un hábito.', 2),
  ('Teens 3', 'L9', 'Lesson 9 · Phrasal Verbs in Context', 'Verbos compuestos separables e inseparables para la vida diaria y el trabajo', '🧩', 'multiple_choice', 'Can you ___ my dog this weekend while I am traveling?', '["look after", "look for", "look up", "look forward to"]'::jsonb, 'look after', '«Look after» = cuidar a alguien; «look for» = buscar; «look up» = buscar información en un diccionario/lista.', 3),
  ('Teens 3', 'L9', 'Lesson 9 · Phrasal Verbs in Context', 'Verbos compuestos separables e inseparables para la vida diaria y el trabajo', '🧩', 'multiple_choice', 'With separable phrasal verbs like «turn off», which sentence is grammatically INCORRECT?', '["Turn off it.", "Turn it off.", "Turn the light off.", "Turn off the light."]'::jsonb, 'Turn off it.', 'Cuando el objeto de un phrasal verb separable es un pronombre (it, them), DEBE ir en el medio: «Turn it off» (nunca «Turn off it»).', 4),
  ('Teens 3', 'L9', 'Lesson 9 · Phrasal Verbs in Context', 'Verbos compuestos separables e inseparables para la vida diaria y el trabajo', '🧩', 'multiple_choice', 'Don''t ___ until tomorrow what you can do today!', '["put off", "call off", "get along", "bring up"]'::jsonb, 'put off', '«Put off» significa posponer o postergar; «call off» significa cancelar por completo.', 5),
  ('Teens 3', 'L10', 'Lesson 10 · Relative Clauses (Who, Which, That, Whose, Where)', 'Cláusulas relativas especificativas y explicativas con who, which, whose, where, when', '🔗', 'multiple_choice', 'An architect is a professional ___ designs buildings and bridges.', '["who", "which", "whose", "where"]'::jsonb, 'who', 'Usamos «who» (o «that») para referirnos a personas.', 1),
  ('Teens 3', 'L10', 'Lesson 10 · Relative Clauses (Who, Which, That, Whose, Where)', 'Cláusulas relativas especificativas y explicativas con who, which, whose, where, when', '🔗', 'multiple_choice', 'That is the woman ___ daughter won the national scholarship.', '["whose", "who", "which", "whom"]'::jsonb, 'whose', '«Whose» es el pronombre relativo posesivo («cuyo / cuya»): whose daughter = cuya hija.', 2),
  ('Teens 3', 'L10', 'Lesson 10 · Relative Clauses (Who, Which, That, Whose, Where)', 'Cláusulas relativas especificativas y explicativas con who, which, whose, where, when', '🔗', 'multiple_choice', 'Mérida is the city ___ my grandparents met fifty years ago.', '["where", "which", "who", "whose"]'::jsonb, 'where', 'Para indicar el lugar donde ocurre una acción dentro de la cláusula relativa usamos «where».', 3),
  ('Teens 3', 'L10', 'Lesson 10 · Relative Clauses (Who, Which, That, Whose, Where)', 'Cláusulas relativas especificativas y explicativas con who, which, whose, where, when', '🔗', 'multiple_choice', 'My laptop, ___ I bought last year, works extremely fast. (Note the commas!)', '["which", "that", "who", "where"]'::jsonb, 'which', 'En cláusulas relativas explicativas entre comas (non-defining), NO se puede usar «that»; para cosas usamos «which».', 4),
  ('Teens 3', 'L10', 'Lesson 10 · Relative Clauses (Who, Which, That, Whose, Where)', 'Cláusulas relativas especificativas y explicativas con who, which, whose, where, when', '🔗', 'multiple_choice', 'The book ___ you recommended to me was fascinating.', '["that / which", "who", "whose", "where"]'::jsonb, 'that / which', 'Para objetos o cosas en cláusulas sin comas podemos usar tanto «that» como «which».', 5),
  ('Adultos 1', 'L1', 'Lesson 1 · The English Alphabet, Spelling & Professions', 'Abecedario, deletreo, ocupaciones y frases de clase', '🔤', 'multiple_choice', 'How many letters and vowels are there in the English alphabet?', '["26 letters and 5 vowels", "27 letters and 5 vowels", "26 letters and 6 vowels", "24 letters and 5 vowels"]'::jsonb, '26 letters and 5 vowels', 'El abecedario en inglés tiene 26 letras en total y 5 vocales (A, E, I, O, U).', 1),
  ('Adultos 1', 'L1', 'Lesson 1 · The English Alphabet, Spelling & Professions', 'Abecedario, deletreo, ocupaciones y frases de clase', '🔤', 'multiple_choice', 'A: ___ do you spell your last name? — B: R - O - J - A - S.', '["How", "What", "Where", "Who"]'::jsonb, 'How', 'Para preguntar cómo se deletrea una palabra o nombre usamos siempre: «How do you spell...?».', 2),
  ('Adultos 1', 'L1', 'Lesson 1 · The English Alphabet, Spelling & Professions', 'Abecedario, deletreo, ocupaciones y frases de clase', '🔤', 'multiple_choice', 'In emails and usernames, how do we say the symbols «@» and «_» in English?', '["at / underscore", "in / dash", "at / point", "around / line"]'::jsonb, 'at / underscore', 'En usuarios y correos electrónicos, «@» se dice «at», «.» se dice «dot» y «_» se dice «underscore».', 3),
  ('Adultos 1', 'L1', 'Lesson 1 · The English Alphabet, Spelling & Professions', 'Abecedario, deletreo, ocupaciones y frases de clase', '🔤', 'multiple_choice', 'My sister works in a hospital and helps sick patients. She is a ___.', '["nurse", "lawyer", "architect", "accountant"]'::jsonb, 'nurse', '«Nurse» significa enfermera/o; «lawyer» es abogado/a y «accountant» es contador/a.', 4),
  ('Adultos 1', 'L1', 'Lesson 1 · The English Alphabet, Spelling & Professions', 'Abecedario, deletreo, ocupaciones y frases de clase', '🔤', 'multiple_choice', 'Which classroom phrase do you use when you don''t know a word in English?', '["How do you say ___ in English?", "Where are you from?", "Nice to meet you!", "See you tomorrow!"]'::jsonb, 'How do you say ___ in English?', '«How do you say ___ in English?» es la frase clave del salón para preguntar vocabulario nuevo.', 5),
  ('Adultos 1', 'L2', 'Lesson 2 · Personal Pronouns, Verb To Be, Family & Articles', 'Am / is / are, artículos a/an/the, países y familia', '👨‍👩‍👧‍👦', 'multiple_choice', 'Carlos and I ___ from Venezuela. We ___ students at Living English.', '["are / are", "am / are", "is / are", "are / is"]'::jsonb, 'are / are', '«Carlos and I» equivale al pronombre «We» (nosotros), que siempre usa la forma «are» del verbo To Be.', 1),
  ('Adultos 1', 'L2', 'Lesson 2 · Personal Pronouns, Verb To Be, Family & Articles', 'Am / is / are, artículos a/an/the, países y familia', '👨‍👩‍👧‍👦', 'multiple_choice', 'My uncle is ___ engineer and my aunt is ___ teacher.', '["an / a", "a / an", "a / a", "an / an"]'::jsonb, 'an / a', 'Usamos «an» antes de sonido vocálico (an engineer) y «a» antes de sonido consonántico (a teacher).', 2),
  ('Adultos 1', 'L2', 'Lesson 2 · Personal Pronouns, Verb To Be, Family & Articles', 'Am / is / are, artículos a/an/the, países y familia', '👨‍👩‍👧‍👦', 'multiple_choice', 'A: ___ your sister a doctor? — B: No, she ___. She is a lawyer.', '["Is / isn''t", "Are / aren''t", "Am / not", "Does / doesn''t"]'::jsonb, 'Is / isn''t', 'Para tercera persona singular (she/he/it) preguntamos con «Is...?» y negamos con «isn''t».', 3),
  ('Adultos 1', 'L2', 'Lesson 2 · Personal Pronouns, Verb To Be, Family & Articles', 'Am / is / are, artículos a/an/the, países y familia', '👨‍👩‍👧‍👦', 'multiple_choice', 'My mother''s brother is my ___, and his daughter is my ___.', '["uncle / cousin", "grandfather / niece", "nephew / aunt", "brother / sister"]'::jsonb, 'uncle / cousin', 'El hermano de mi mamá es mi tío («uncle») y su hija es mi prima («cousin»).', 4),
  ('Adultos 1', 'L2', 'Lesson 2 · Personal Pronouns, Verb To Be, Family & Articles', 'Am / is / are, artículos a/an/the, países y familia', '👨‍👩‍👧‍👦', 'multiple_choice', 'Choose the correct order for physical description in English:', '["She has long brown hair.", "She has hair brown long.", "She is long hair brown.", "She has brown hair long."]'::jsonb, 'She has long brown hair.', 'En inglés los adjetivos van ANTES del sustantivo (tamaño + color + sustantivo: long brown hair).', 5),
  ('Adultos 1', 'L3', 'Lesson 3 · Plural Nouns, Food, Some / Any & Demonstratives', 'Plurales regulares e irregulares, some/any, how much/many, this/that/these/those', '🍎', 'multiple_choice', 'What is the correct plural form of: «child», «tooth», and «woman»?', '["children, teeth, women", "childs, tooths, womans", "childrens, teeths, women", "children, tooths, womens"]'::jsonb, 'children, teeth, women', 'Son plurales irregulares: child → children, tooth → teeth, woman → women.', 1),
  ('Adultos 1', 'L3', 'Lesson 3 · Plural Nouns, Food, Some / Any & Demonstratives', 'Plurales regulares e irregulares, some/any, how much/many, this/that/these/those', '🍎', 'multiple_choice', 'There isn''t ___ milk in the fridge, but there are ___ apples on the table.', '["any / some", "some / any", "many / much", "a / an"]'::jsonb, 'any / some', 'Usamos «any» en oraciones negativas e interrogativas, y «some» en oraciones afirmativas.', 2),
  ('Adultos 1', 'L3', 'Lesson 3 · Plural Nouns, Food, Some / Any & Demonstratives', 'Plurales regulares e irregulares, some/any, how much/many, this/that/these/those', '🍎', 'multiple_choice', '___ sugar do you want in your coffee, and ___ oranges do we need?', '["How much / how many", "How many / how much", "How much / how much", "Some / any"]'::jsonb, 'How much / how many', '«How much» se usa con incontables (sugar, water, money) y «How many» con contables en plural (oranges).', 3),
  ('Adultos 1', 'L3', 'Lesson 3 · Plural Nouns, Food, Some / Any & Demonstratives', 'Plurales regulares e irregulares, some/any, how much/many, this/that/these/those', '🍎', 'multiple_choice', 'Look at ___ birds up in the sky! And look at ___ book in my hand.', '["those / this", "these / that", "this / those", "that / these"]'::jsonb, 'those / this', '«Those» es para plural lejos (birds in the sky) y «this» es para singular cerca (in my hand).', 4),
  ('Adultos 1', 'L3', 'Lesson 3 · Plural Nouns, Food, Some / Any & Demonstratives', 'Plurales regulares e irregulares, some/any, how much/many, this/that/these/those', '🍎', 'multiple_choice', 'What is the plural of «city» and «box»?', '["cities / boxes", "citys / boxs", "cities / boxies", "cityes / boxes"]'::jsonb, 'cities / boxes', 'Consonante + y cambia a «-ies» (cities); palabras terminadas en -s, -sh, -ch, -x agregan «-es» (boxes).', 5),
  ('Adultos 1', 'L4', 'Lesson 4 · Simple Present (Do / Does) & Question Words', 'Rutinas en presente simple, tercera persona (-s/-es), do vs. make', '⚡', 'multiple_choice', 'Sofía ___ English every afternoon, and her brothers ___ soccer.', '["studies / play", "study / plays", "studies / plays", "studys / play"]'::jsonb, 'studies / play', 'En 3ra persona singular (Sofía = she) «study» pasa a «studies». En plural (her brothers = they) el verbo va en forma base «play».', 1),
  ('Adultos 1', 'L4', 'Lesson 4 · Simple Present (Do / Does) & Question Words', 'Rutinas en presente simple, tercera persona (-s/-es), do vs. make', '⚡', 'multiple_choice', 'A: ___ your father work on Saturdays? — B: No, he ___.', '["Does / doesn''t", "Do / don''t", "Is / isn''t", "Does / don''t"]'::jsonb, 'Does / doesn''t', 'Con he/she/it usamos el auxiliar «Does» para preguntar y «doesn''t» para responder en negativo.', 2),
  ('Adultos 1', 'L4', 'Lesson 4 · Simple Present (Do / Does) & Question Words', 'Rutinas en presente simple, tercera persona (-s/-es), do vs. make', '⚡', 'multiple_choice', 'Every morning I ___ my bed, and at night I ___ my English homework.', '["make / do", "do / make", "make / make", "do / do"]'::jsonb, 'make / do', 'Decimos «make the bed / make breakfast / make a mistake» pero «do homework / do exercises / do housework».', 3),
  ('Adultos 1', 'L4', 'Lesson 4 · Simple Present (Do / Does) & Question Words', 'Rutinas en presente simple, tercera persona (-s/-es), do vs. make', '⚡', 'multiple_choice', '___ do you usually have lunch with? — With my coworkers.', '["Who", "Where", "When", "Why"]'::jsonb, 'Who', '«Who ... with?» pregunta «¿Con quién...?» (preposición al final de la pregunta).', 4),
  ('Adultos 1', 'L4', 'Lesson 4 · Simple Present (Do / Does) & Question Words', 'Rutinas en presente simple, tercera persona (-s/-es), do vs. make', '⚡', 'multiple_choice', 'She doesn''t ___ coffee at night because she wants to sleep well.', '["drink", "drinks", "drinking", "to drink"]'::jsonb, 'drink', 'Después de «doesn''t» o «don''t», el verbo principal va SIEMPRE en su forma base sin «-s» (drink).', 5),
  ('Adultos 1', 'L4B', 'Lesson 4B · Present Continuous vs. Simple Present', 'Acciones ahora mismo (am/is/are + -ing) vs. hábitos y rutinas', '🎬', 'multiple_choice', 'Look! It ___ outside right now. Take your umbrella!', '["is raining", "rains", "rain", "are raining"]'::jsonb, 'is raining', 'Para algo que está ocurriendo en este preciso momento («Look! / right now») usamos Present Continuous (is + -ing).', 1),
  ('Adultos 1', 'L4B', 'Lesson 4B · Present Continuous vs. Simple Present', 'Acciones ahora mismo (am/is/are + -ing) vs. hábitos y rutinas', '🎬', 'multiple_choice', 'My mom usually ___ dinner, but tonight my dad ___ pizza.', '["cooks / is making", "is cooking / makes", "cook / is making", "cooks / makes"]'::jsonb, 'cooks / is making', '«Usually» indica hábito (Simple Present: cooks) y «tonight / right now» indica acción temporal en progreso (is making).', 2),
  ('Adultos 1', 'L4B', 'Lesson 4B · Present Continuous vs. Simple Present', 'Acciones ahora mismo (am/is/are + -ing) vs. hábitos y rutinas', '🎬', 'multiple_choice', 'What is the correct -ing spelling of «swim», «write», and «run»?', '["swimming, writing, running", "swiming, writeing, runing", "swimming, writting, running", "swiming, writing, running"]'::jsonb, 'swimming, writing, running', 'Verbos cortos CVC duplican la última consonante (swimming, running); verbos terminados en -e muda la eliminan (writing).', 3),
  ('Adultos 1', 'L4B', 'Lesson 4B · Present Continuous vs. Simple Present', 'Acciones ahora mismo (am/is/are + -ing) vs. hábitos y rutinas', '🎬', 'multiple_choice', 'A: What ___ the children doing? — B: They ___ playing in the yard.', '["are / are", "do / are", "is / are", "are / do"]'::jsonb, 'are / are', '«The children» es plural (they), por lo que usa «are» tanto en la pregunta como en la respuesta.', 4),
  ('Adultos 1', 'L4B', 'Lesson 4B · Present Continuous vs. Simple Present', 'Acciones ahora mismo (am/is/are + -ing) vs. hábitos y rutinas', '🎬', 'multiple_choice', 'I ___ English every week, and right now I ___ a practice exercise.', '["study / am doing", "am studying / do", "studies / am doing", "study / do"]'::jsonb, 'study / am doing', '«Every week» = rutina (study); «right now» = en progreso ahora mismo (am doing).', 5),
  ('Adultos 1', 'L5', 'Lesson 5 · Numbers, Dates, Years & Telling the Time', 'Números ordinales, fechas, años, meses y cómo decir la hora', '⏰', 'multiple_choice', 'How do you write and say the ordinal numbers 1st, 2nd, and 3rd?', '["first, second, third", "oneth, twoth, threeth", "first, twosecond, third", "one, two, three"]'::jsonb, 'first, second, third', 'Para fechas y posiciones usamos números ordinales: 1st = first, 2nd = second, 3rd = third, 4th = fourth.', 1),
  ('Adultos 1', 'L5', 'Lesson 5 · Numbers, Dates, Years & Telling the Time', 'Números ordinales, fechas, años, meses y cómo decir la hora', '⏰', 'multiple_choice', 'It''s 7:45. What is another natural way to say this time in English?', '["It''s a quarter to eight.", "It''s a quarter past seven.", "It''s half past seven.", "It''s fifteen to seven."]'::jsonb, 'It''s a quarter to eight.', '7:45 = faltan 15 minutos (un cuarto) para las ocho: «It''s a quarter to eight».', 2),
  ('Adultos 1', 'L5', 'Lesson 5 · Numbers, Dates, Years & Telling the Time', 'Números ordinales, fechas, años, meses y cómo decir la hora', '⏰', 'multiple_choice', 'It''s 3:30. How do we say this time?', '["It''s half past three.", "It''s a quarter to three.", "It''s thirty to four.", "It''s half to three."]'::jsonb, 'It''s half past three.', 'Las y media se expresan con «half past + hora»: 3:30 = It''s half past three (o three thirty).', 3),
  ('Adultos 1', 'L5', 'Lesson 5 · Numbers, Dates, Years & Telling the Time', 'Números ordinales, fechas, años, meses y cómo decir la hora', '⏰', 'multiple_choice', 'How do we read the year «1998» and «2027» in English?', '["nineteen ninety-eight / twenty twenty-seven", "one九nine-eight / two twenty-seven", "nineteen hundred eight / two thousand seven", "ninety-eight / twenty-seven"]'::jsonb, 'nineteen ninety-eight / twenty twenty-seven', 'Los años de 4 cifras suelen dividirse en dos pares de números: 19-98 (nineteen ninety-eight) y 20-27 (twenty twenty-seven).', 4),
  ('Adultos 1', 'L5', 'Lesson 5 · Numbers, Dates, Years & Telling the Time', 'Números ordinales, fechas, años, meses y cómo decir la hora', '⏰', 'multiple_choice', 'What time ___ you wake up on Mondays? — I wake up ___ 6:30 am.', '["do / at", "are / on", "does / in", "do / in"]'::jsonb, 'do / at', 'Para horas exactas del reloj usamos siempre la preposición «at» (at 6:30 am).', 5),
  ('Adultos 1', 'L6', 'Lesson 6 · Prepositions of Time & Place + Directions', 'Uso de IN / ON / AT, lugares de la ciudad y cómo dar direcciones', '🗺️', 'multiple_choice', 'My birthday is ___ July, ___ July 15th, and the party starts ___ 8:00 pm.', '["in / on / at", "on / in / at", "in / at / on", "at / on / in"]'::jsonb, 'in / on / at', 'Regla de oro: IN para meses y años (in July), ON para días y fechas específicas (on July 15th) y AT para horas (at 8:00 pm).', 1),
  ('Adultos 1', 'L6', 'Lesson 6 · Prepositions of Time & Place + Directions', 'Uso de IN / ON / AT, lugares de la ciudad y cómo dar direcciones', '🗺️', 'multiple_choice', 'The pharmacy is ___ the bank and the bakery.', '["between", "among", "in", "under"]'::jsonb, 'between', '«Between» significa «entre dos lugares específicos» (between the bank and the bakery).', 2),
  ('Adultos 1', 'L6', 'Lesson 6 · Prepositions of Time & Place + Directions', 'Uso de IN / ON / AT, lugares de la ciudad y cómo dar direcciones', '🗺️', 'multiple_choice', 'Excuse me, how can I get to the museum? — Go ___ ahead for two blocks and ___ left.', '["straight / turn", "direct / go", "front / make", "up / walk"]'::jsonb, 'straight / turn', 'Para dar direcciones usamos «Go straight ahead» (sigue derecho) y «turn left / turn right» (cruza a la izquierda/derecha).', 3),
  ('Adultos 1', 'L6', 'Lesson 6 · Prepositions of Time & Place + Directions', 'Uso de IN / ON / AT, lugares de la ciudad y cómo dar direcciones', '🗺️', 'multiple_choice', 'The bus stop is right ___ of the hospital, on the other side of the street.', '["across from", "inside", "under", "between"]'::jsonb, 'across from', '«Across from» (o «in front of / opposite») indica que está cruzando la calle, frente al otro lugar.', 4),
  ('Adultos 1', 'L6', 'Lesson 6 · Prepositions of Time & Place + Directions', 'Uso de IN / ON / AT, lugares de la ciudad y cómo dar direcciones', '🗺️', 'multiple_choice', 'We never have classes ___ Sundays, but we study ___ the morning.', '["on / in", "in / on", "at / in", "on / at"]'::jsonb, 'on / in', 'Usamos «on» con los días de la semana (on Sundays) e «in» con las partes del día (in the morning / afternoon / evening).', 5),
  ('Adultos 1', 'L7', 'Lesson 7 · Past of Verb To Be: Was / Were', 'Pasado del verbo To Be (was, were, wasn''t, weren''t) y expresiones de pasado', '⏳', 'multiple_choice', 'Where ___ you yesterday evening? — I ___ at the cinema with my friends.', '["were / was", "was / were", "were / were", "did / was"]'::jsonb, 'were / was', 'Con «you/we/they» usamos «were», y con «I/he/she/it» usamos «was».', 1),
  ('Adultos 1', 'L7', 'Lesson 7 · Past of Verb To Be: Was / Were', 'Pasado del verbo To Be (was, were, wasn''t, weren''t) y expresiones de pasado', '⏳', 'multiple_choice', 'The weather ___ cold last weekend; it ___ sunny and warm!', '["wasn''t / was", "weren''t / were", "didn''t / was", "isn''t / is"]'::jsonb, 'wasn''t / was', '«The weather» (it) es singular, por lo que en pasado usa «wasn''t» y «was».', 2),
  ('Adultos 1', 'L7', 'Lesson 7 · Past of Verb To Be: Was / Were', 'Pasado del verbo To Be (was, were, wasn''t, weren''t) y expresiones de pasado', '⏳', 'multiple_choice', 'A: ___ they tired after the soccer match? — B: Yes, they ___.', '["Were / were", "Was / was", "Did / did", "Are / are"]'::jsonb, 'Were / were', 'Con «they» preguntamos «Were they...?» y respondemos «Yes, they were.»', 3),
  ('Adultos 1', 'L7', 'Lesson 7 · Past of Verb To Be: Was / Were', 'Pasado del verbo To Be (was, were, wasn''t, weren''t) y expresiones de pasado', '⏳', 'multiple_choice', 'When ___ your brother born? — He ___ born in 2010.', '["was / was", "were / was", "did / is", "is / was"]'::jsonb, 'was / was', 'En inglés «nacer» se expresa en pasado pasivo con To Be: «He was born in...».', 4),
  ('Adultos 1', 'L7', 'Lesson 7 · Past of Verb To Be: Was / Were', 'Pasado del verbo To Be (was, were, wasn''t, weren''t) y expresiones de pasado', '⏳', 'multiple_choice', 'Which time expression is used with the Past Tense (was / were)?', '["two days ago", "next week", "tomorrow morning", "right now"]'::jsonb, 'two days ago', '«Ago» (two days ago = hace dos días), «yesterday» y «last night» indican tiempo pasado.', 5),
  ('Adultos 1', 'L8', 'Lesson 8 · Simple Future: Will & Be Going To', 'Futuro con Will / Won''t y planes con Am/Is/Are Going To', '🚀', 'multiple_choice', 'Look at those dark clouds! It ___ rain in a few minutes.', '["is going to", "will be", "going to", "wills"]'::jsonb, 'is going to', 'Usamos «be going to» para planes ya decididos o predicciones con evidencia visible ahora mismo (nubes oscuras).', 1),
  ('Adultos 1', 'L8', 'Lesson 8 · Simple Future: Will & Be Going To', 'Futuro con Will / Won''t y planes con Am/Is/Are Going To', '🚀', 'multiple_choice', 'Don''t worry about the heavy bag. I ___ help you carry it!', '["will", "am going", "going to", "did"]'::jsonb, 'will', 'Usamos «will» para decisiones espontáneas tomadas en el momento de hablar, promesas y ofrecimientos.', 2),
  ('Adultos 1', 'L8', 'Lesson 8 · Simple Future: Will & Be Going To', 'Futuro con Will / Won''t y planes con Am/Is/Are Going To', '🚀', 'multiple_choice', 'What is the negative contraction of «will not»?', '["won''t", "willn''t", "don''t will", "not will"]'::jsonb, 'won''t', 'La forma negativa contraída de «will not» es «won''t» (She won''t arrive late).', 3),
  ('Adultos 1', 'L8', 'Lesson 8 · Simple Future: Will & Be Going To', 'Futuro con Will / Won''t y planes con Am/Is/Are Going To', '🚀', 'multiple_choice', 'Next year we ___ travel to Madrid to visit our cousins.', '["are going to", "going to", "will to", "is going to"]'::jsonb, 'are going to', 'La estructura completa requiere el verbo To Be antes de «going to»: We + are going to + verbo.', 4),
  ('Adultos 1', 'L8', 'Lesson 8 · Simple Future: Will & Be Going To', 'Futuro con Will / Won''t y planes con Am/Is/Are Going To', '🚀', 'multiple_choice', 'A: ___ she be at the meeting tomorrow? — B: Yes, she ___.', '["Will / will", "Is / will", "Does / will", "Will / is"]'::jsonb, 'Will / will', 'Las preguntas con «Will» se responden de forma corta con «Yes, she will / No, she won''t».', 5),
  ('Adultos 2', 'Review', 'Review · The 4 Simple Tenses & Phrases to Gain Time', 'Repaso de To Be, Do/Does, Was/Were, Will y muletillas conversacionales', '🔄', 'multiple_choice', '___ your mother cook arepas on weekends? — Yes, she ___.', '["Does / does", "Is / is", "Do / do", "Did / does"]'::jsonb, 'Does / does', 'Con un verbo de acción («cook») en presente simple y 3ra persona singular usamos el auxiliar «Does».', 1),
  ('Adultos 2', 'Review', 'Review · The 4 Simple Tenses & Phrases to Gain Time', 'Repaso de To Be, Do/Does, Was/Were, Will y muletillas conversacionales', '🔄', 'multiple_choice', 'They ___ at home last night because they went to a concert.', '["weren''t", "didn''t", "don''t", "wasn''t"]'::jsonb, 'weren''t', 'Para estar en un lugar en pasado («at home last night») con «they» usamos «weren''t».', 2),
  ('Adultos 2', 'Review', 'Review · The 4 Simple Tenses & Phrases to Gain Time', 'Repaso de To Be, Do/Does, Was/Were, Will y muletillas conversacionales', '🔄', 'multiple_choice', 'Which phrase is best to gain time while thinking in a conversation without staying silent?', '["Well... let me think...", "Goodbye, see you!", "I don''t speak.", "Repeat the test."]'::jsonb, 'Well... let me think...', 'Frases como «Well... let me think...» o «What I mean is...» te dan tiempo para pensar manteniendo la fluidez.', 3),
  ('Adultos 2', 'Review', 'Review · The 4 Simple Tenses & Phrases to Gain Time', 'Repaso de To Be, Do/Does, Was/Were, Will y muletillas conversacionales', '🔄', 'multiple_choice', 'We ___ travel next month because we have exams at the university.', '["won''t", "weren''t", "doesn''t", "aren''t"]'::jsonb, 'won''t', 'Para negar una acción futura («next month») con «will» usamos «won''t» + verbo base.', 4),
  ('Adultos 2', 'Review', 'Review · The 4 Simple Tenses & Phrases to Gain Time', 'Repaso de To Be, Do/Does, Was/Were, Will y muletillas conversacionales', '🔄', 'multiple_choice', 'Transform into a negative sentence: «He lives in Maracay.»', '["He doesn''t live in Maracay.", "He don''t live in Maracay.", "He isn''t live in Maracay.", "He doesn''t lives in Maracay."]'::jsonb, 'He doesn''t live in Maracay.', 'En negativo de 3ra persona usamos «doesn''t» y el verbo vuelve a su forma base sin -s («live»).', 5),
  ('Adultos 2', 'L1', 'Lesson 1 · Pronouns, There + To Be, Both/Either/Neither & Connectors', 'Pronombres reflexivos e indefinidos, there was/will be, hogar, cine y recetas', '🏠', 'multiple_choice', 'Be careful with that knife! You might cut ___.', '["yourself", "himself", "myself", "yourselves"]'::jsonb, 'yourself', 'El pronombre reflexivo para «you» (singular) es «yourself».', 1),
  ('Adultos 2', 'L1', 'Lesson 1 · Pronouns, There + To Be, Both/Either/Neither & Connectors', 'Pronombres reflexivos e indefinidos, there was/will be, hogar, cine y recetas', '🏠', 'multiple_choice', 'In my future house, ___ a big swimming pool and three bedrooms.', '["there will be", "there is", "there were", "will have"]'::jsonb, 'there will be', '«Habrá» en futuro se dice «there will be» (tanto para singular como para plural).', 2),
  ('Adultos 2', 'L1', 'Lesson 1 · Pronouns, There + To Be, Both/Either/Neither & Connectors', 'Pronombres reflexivos e indefinidos, there was/will be, hogar, cine y recetas', '🏠', 'multiple_choice', 'I knocked on the door, but ___ answered. The house was empty.', '["nobody", "anybody", "somebody", "everybody"]'::jsonb, 'nobody', 'Con verbo en afirmativo («answered»), «nobody / no one» expresa ausencia total («nadie respondió»).', 3),
  ('Adultos 2', 'L1', 'Lesson 1 · Pronouns, There + To Be, Both/Either/Neither & Connectors', 'Pronombres reflexivos e indefinidos, there was/will be, hogar, cine y recetas', '🏠', 'multiple_choice', '___ coffee and tea have caffeine, so I don''t drink ___ of them at night.', '["Both / either", "Either / neither", "Neither / both", "Both / neither"]'::jsonb, 'Both / either', '«Both A and B» = ambos; después de un verbo negativo («don''t drink») usamos «either» (ninguno de los dos).', 4),
  ('Adultos 2', 'L1', 'Lesson 1 · Pronouns, There + To Be, Both/Either/Neither & Connectors', 'Pronombres reflexivos e indefinidos, there was/will be, hogar, cine y recetas', '🏠', 'multiple_choice', 'Which sequence of connectors is best to explain a recipe step by step?', '["First, then, after that, finally", "Because, although, however, so", "Yesterday, ago, last, never", "Who, which, whose, where"]'::jsonb, 'First, then, after that, finally', 'Para ordenar pasos de una receta o historia usamos conectores de secuencia: First, then, next, after that, finally.', 5),
  ('Adultos 2', 'L2', 'Lesson 2 · Simple Past: Regular & Irregular Verbs + DID', 'Verbos regulares (-ed), irregulares y preguntas/negaciones con DID', '✈️', 'multiple_choice', 'Last summer we ___ to Mérida and ___ lots of photos in the mountains.', '["went / took", "go / take", "went / taked", "goed / took"]'::jsonb, 'went / took', 'Ambos son verbos irregulares en pasado: go → went, take → took.', 1),
  ('Adultos 2', 'L2', 'Lesson 2 · Simple Past: Regular & Irregular Verbs + DID', 'Verbos regulares (-ed), irregulares y preguntas/negaciones con DID', '✈️', 'multiple_choice', 'A: Where ___ you go on your last vacation? — B: I ___ to Margarita Island.', '["did / went", "did / go", "were / went", "do / went"]'::jsonb, 'did / went', 'En la pregunta con «did» el verbo va en base («did you go»), pero en la respuesta afirmativa va en pasado («I went»).', 2),
  ('Adultos 2', 'L2', 'Lesson 2 · Simple Past: Regular & Irregular Verbs + DID', 'Verbos regulares (-ed), irregulares y preguntas/negaciones con DID', '✈️', 'multiple_choice', 'She ___ the movie last night because she ___ too tired.', '["didn''t watch / was", "didn''t watched / was", "wasn''t watch / did", "don''t watch / were"]'::jsonb, 'didn''t watch / was', 'Con «didn''t» el verbo queda en base («didn''t watch»); el verbo To Be no usa did sino «was/were».', 3),
  ('Adultos 2', 'L2', 'Lesson 2 · Simple Past: Regular & Irregular Verbs + DID', 'Verbos regulares (-ed), irregulares y preguntas/negaciones con DID', '✈️', 'multiple_choice', 'What is the Simple Past of «buy», «see», and «write»?', '["bought, saw, wrote", "buyed, seed, writed", "bought, seen, written", "brought, saw, wrote"]'::jsonb, 'bought, saw, wrote', 'Pasado simple irregular: buy → bought, see → saw, write → wrote.', 4),
  ('Adultos 2', 'L2', 'Lesson 2 · Simple Past: Regular & Irregular Verbs + DID', 'Verbos regulares (-ed), irregulares y preguntas/negaciones con DID', '✈️', 'multiple_choice', 'How is the -ed ending pronounced in «wanted» and «needed»?', '["/ɪd/ (extra syllable)", "/t/", "/d/", "silent"]'::jsonb, '/ɪd/ (extra syllable)', 'Cuando el verbo termina en sonido /t/ o /d/ (want, need, decide), la terminación «-ed» se pronuncia /ɪd/.', 5),
  ('Adultos 2', 'L3', 'Lesson 3 · Possessive Adjectives & Possessive Pronouns', 'My vs. mine, your vs. yours, her vs. hers, their vs. theirs, Whose...?', '🔑', 'multiple_choice', 'This is not ___ umbrella. ___ is blue, and this one is black.', '["my / Mine", "mine / My", "my / My", "me / Mine"]'::jsonb, 'my / Mine', '«My» es adjetivo posesivo (va antes del sustantivo: my umbrella); «Mine» es pronombre posesivo (reemplaza al sustantivo).', 1),
  ('Adultos 2', 'L3', 'Lesson 3 · Possessive Adjectives & Possessive Pronouns', 'My vs. mine, your vs. yours, her vs. hers, their vs. theirs, Whose...?', '🔑', 'multiple_choice', 'A: ___ notebook is this on the desk? — B: It''s ___ (belonging to María).', '["Whose / hers", "Who''s / her", "Whose / her", "Who / hers"]'::jsonb, 'Whose / hers', '«Whose» pregunta «¿De quién?» y «hers» significa «el/la de ella» sin repetir el sustantivo.', 2),
  ('Adultos 2', 'L3', 'Lesson 3 · Possessive Adjectives & Possessive Pronouns', 'My vs. mine, your vs. yours, her vs. hers, their vs. theirs, Whose...?', '🔑', 'multiple_choice', 'We love ___ academy, and the students in the other classroom love ___ too.', '["our / theirs", "ours / their", "our / their", "ours / theirs"]'::jsonb, 'our / theirs', '«Our» acompaña a «academy»; «theirs» va solo al final significando «la de ellos».', 3),
  ('Adultos 2', 'L3', 'Lesson 3 · Possessive Adjectives & Possessive Pronouns', 'My vs. mine, your vs. yours, her vs. hers, their vs. theirs, Whose...?', '🔑', 'multiple_choice', 'Is that car ___? — Yes, they bought it last week.', '["theirs", "their", "them", "they''re"]'::jsonb, 'theirs', 'Como no sigue ningún sustantivo después, usamos el pronombre posesivo «theirs».', 4),
  ('Adultos 2', 'L3', 'Lesson 3 · Possessive Adjectives & Possessive Pronouns', 'My vs. mine, your vs. yours, her vs. hers, their vs. theirs, Whose...?', '🔑', 'multiple_choice', 'The dog wagged ___ tail happily when it saw ___ owner.', '["its / its", "it''s / its", "its / it''s", "his / it''s"]'::jsonb, 'its / its', '«Its» (sin apóstrofo) es el posesivo de cosas o animales; «it''s» con apóstrofo significa «it is».', 5),
  ('Adultos 2', 'L4', 'Lesson 4 · Past Habits: Used To vs. Be Used To', 'Hábitos del pasado (used to + verbo) vs. estar acostumbrado a (be used to + -ing)', '🚲', 'multiple_choice', 'When I was a child, I ___ play video games all afternoon, but now I''m busy.', '["used to", "use to", "am used to", "was used to"]'::jsonb, 'used to', '«Used to + verbo base» expresa un hábito o estado en el pasado que ya no ocurre en el presente.', 1),
  ('Adultos 2', 'L4', 'Lesson 4 · Past Habits: Used To vs. Be Used To', 'Hábitos del pasado (used to + verbo) vs. estar acostumbrado a (be used to + -ing)', '🚲', 'multiple_choice', 'She ___ like coffee before, but now she drinks two cups every morning.', '["didn''t use to", "didn''t used to", "wasn''t use to", "not used to"]'::jsonb, 'didn''t use to', 'En negativo e interrogativo con «did/didn''t», «used to» pierde la «d» y se escribe «use to».', 2),
  ('Adultos 2', 'L4', 'Lesson 4 · Past Habits: Used To vs. Be Used To', 'Hábitos del pasado (used to + verbo) vs. estar acostumbrado a (be used to + -ing)', '🚲', 'multiple_choice', 'I live in a big city now, so I ___ the heavy traffic and noise.', '["am used to", "used to", "use to", "did use to"]'::jsonb, 'am used to', '«Be used to + sustantivo o verbo -ing» significa «estar acostumbrado a algo» en el presente.', 3),
  ('Adultos 2', 'L4', 'Lesson 4 · Past Habits: Used To vs. Be Used To', 'Hábitos del pasado (used to + verbo) vs. estar acostumbrado a (be used to + -ing)', '🚲', 'multiple_choice', 'Doctors are used to ___ long hours at the hospital.', '["working", "work", "worked", "works"]'::jsonb, 'working', 'Después de «be used to» o «get used to», el verbo lleva siempre «-ing» porque «to» aquí es preposición.', 4),
  ('Adultos 2', 'L4', 'Lesson 4 · Past Habits: Used To vs. Be Used To', 'Hábitos del pasado (used to + verbo) vs. estar acostumbrado a (be used to + -ing)', '🚲', 'multiple_choice', '___ you ___ live in Valencia before moving to Caracas?', '["Did / use to", "Did / used to", "Were / use to", "Are / used to"]'::jsonb, 'Did / use to', 'Pregunta sobre hábito pasado: «Did + sujeto + use to + verbo base?».', 5),
  ('Adultos 2', 'L5', 'Lesson 5 · Adjectives -ED vs. -ING & Adjective Order', 'Diferencia entre adjetivos con -ed y -ing y orden correcto de los adjetivos', '🎭', 'multiple_choice', 'The lecture was really ___, so many students felt ___ and sleepy.', '["boring / bored", "bored / boring", "boring / boring", "bored / bored"]'::jsonb, 'boring / bored', 'Los adjetivos con «-ing» describen lo que causa la emoción (the lecture was boring) y con «-ed» cómo se siente la persona (felt bored).', 1),
  ('Adultos 2', 'L5', 'Lesson 5 · Adjectives -ED vs. -ING & Adjective Order', 'Diferencia entre adjetivos con -ed y -ing y orden correcto de los adjetivos', '🎭', 'multiple_choice', 'We are very ___ about our trip to London next month! It will be an ___ experience.', '["excited / exciting", "exciting / excited", "excited / excited", "exciting / exciting"]'::jsonb, 'excited / exciting', 'Nosotros nos sentimos «excited» (-ed); la experiencia es «exciting» (-ing).', 2),
  ('Adultos 2', 'L5', 'Lesson 5 · Adjectives -ED vs. -ING & Adjective Order', 'Diferencia entre adjetivos con -ed y -ing y orden correcto de los adjetivos', '🎭', 'multiple_choice', 'Choose the correct order of adjectives (OSASCOMP):', '["a beautiful small old Italian car", "an Italian old small beautiful car", "a small beautiful Italian old car", "an old Italian beautiful small car"]'::jsonb, 'a beautiful small old Italian car', 'El orden natural en inglés es: Opinion (beautiful) → Size (small) → Age (old) → Origin (Italian) + sustantivo.', 3),
  ('Adultos 2', 'L5', 'Lesson 5 · Adjectives -ED vs. -ING & Adjective Order', 'Diferencia entre adjetivos con -ed y -ing y orden correcto de los adjetivos', '🎭', 'multiple_choice', 'She bought a ___ jacket at the mall yesterday.', '["nice new black leather", "leather black new nice", "black leather nice new", "new black nice leather"]'::jsonb, 'nice new black leather', 'Orden OSASCOMP: Opinion (nice) → Age (new) → Color (black) → Material (leather).', 4),
  ('Adultos 2', 'L5', 'Lesson 5 · Adjectives -ED vs. -ING & Adjective Order', 'Diferencia entre adjetivos con -ed y -ing y orden correcto de los adjetivos', '🎭', 'multiple_choice', 'That horror movie was ___! I was ___ the whole time.', '["terrifying / terrified", "terrified / terrifying", "terrify / terrifying", "terrified / terrified"]'::jsonb, 'terrifying / terrified', 'La película causa miedo («terrifying») y yo sentí miedo («terrified»).', 5),
  ('Adultos 2', 'L6', 'Lesson 6 · Comparatives & Superlatives', 'Comparativos (-er / more), superlativos (-est / the most), igualdades e irregulares', '🏆', 'multiple_choice', 'A plane ticket is ___ than a bus ticket, but flying is much ___.', '["more expensive / faster", "expensiver / more fast", "most expensive / fastest", "more expensive / more fast"]'::jsonb, 'more expensive / faster', 'Adjetivos largos usan «more ... than» (more expensive); adjetivos cortos agregan «-er» (faster).', 1),
  ('Adultos 2', 'L6', 'Lesson 6 · Comparatives & Superlatives', 'Comparativos (-er / more), superlativos (-est / the most), igualdades e irregulares', '🏆', 'multiple_choice', 'Angel Falls is ___ waterfall in the world!', '["the highest", "higher than", "the most high", "highest"]'::jsonb, 'the highest', 'Para el superlativo de un adjetivo corto usamos «the + adjetivo-est» (the highest).', 2),
  ('Adultos 2', 'L6', 'Lesson 6 · Comparatives & Superlatives', 'Comparativos (-er / more), superlativos (-est / the most), igualdades e irregulares', '🏆', 'multiple_choice', 'What are the comparative and superlative forms of «good» and «bad»?', '["better – the best / worse – the worst", "gooder – the goodest / badder – the baddest", "more good / more bad", "better – the best / badder – the worst"]'::jsonb, 'better – the best / worse – the worst', 'Son irregulares: good → better → the best; bad → worse → the worst.', 3),
  ('Adultos 2', 'L6', 'Lesson 6 · Comparatives & Superlatives', 'Comparativos (-er / more), superlativos (-est / the most), igualdades e irregulares', '🏆', 'multiple_choice', 'This laptop is just ___ fast ___ the new model, and it costs less!', '["as / as", "more / than", "so / than", "as / than"]'::jsonb, 'as / as', 'Para comparaciones de igualdad usamos «as + adjetivo + as» (tan rápido como).', 4),
  ('Adultos 2', 'L6', 'Lesson 6 · Comparatives & Superlatives', 'Comparativos (-er / more), superlativos (-est / the most), igualdades e irregulares', '🏆', 'multiple_choice', 'Yesterday was ___ day of the year so far.', '["the hottest", "the hotter", "the most hot", "hotter than"]'::jsonb, 'the hottest', '«Hot» es CVC (consonante-vocal-consonante), por lo que duplica la «t» en el superlativo: «the hottest».', 5),
  ('Adultos 2', 'L7', 'Lesson 7 · Adverbs of Manner & Frequency', 'Adjetivo vs. adverbio (-ly, well, fast, hard) y posición de adverbios de frecuencia', '🎯', 'multiple_choice', 'Sofía is a very ___ pianist; she plays the piano ___.', '["good / well", "well / good", "good / goodly", "good / good"]'::jsonb, 'good / well', '«Good» es adjetivo (describe a pianist) y «well» es su adverbio irregular (describe cómo toca: plays well).', 1),
  ('Adultos 2', 'L7', 'Lesson 7 · Adverbs of Manner & Frequency', 'Adjetivo vs. adverbio (-ly, well, fast, hard) y posición de adverbios de frecuencia', '🎯', 'multiple_choice', 'Please drive ___! It is raining ___ tonight.', '["carefully / heavily", "careful / heavy", "carefully / heavy", "careful / heavily"]'::jsonb, 'carefully / heavily', 'Para describir cómo se realiza un verbo (drive, raining) usamos adverbios terminados en «-ly».', 2),
  ('Adultos 2', 'L7', 'Lesson 7 · Adverbs of Manner & Frequency', 'Adjetivo vs. adverbio (-ly, well, fast, hard) y posición de adverbios de frecuencia', '🎯', 'multiple_choice', 'He works very ___ and runs very ___. (Be careful with irregular adverbs!)', '["hard / fast", "hardly / fastly", "hard / fastly", "hardly / fast"]'::jsonb, 'hard / fast', '«Hard» y «fast» tienen la misma forma como adjetivo y como adverbio («hardly» significa «apenas/casi no» y «fastly» no existe).', 3),
  ('Adultos 2', 'L7', 'Lesson 7 · Adverbs of Manner & Frequency', 'Adjetivo vs. adverbio (-ly, well, fast, hard) y posición de adverbios de frecuencia', '🎯', 'multiple_choice', 'Choose the sentence with the correct position of the frequency adverb:', '["She is never late, and she always arrives early.", "She never is late, and she arrives always early.", "Never she is late, and always she arrives.", "She is late never, and she always arrives early."]'::jsonb, 'She is never late, and she always arrives early.', 'Los adverbios de frecuencia van DESPUÉS del verbo To Be (is never) y ANTES de los demás verbos (always arrives).', 4),
  ('Adultos 2', 'L7', 'Lesson 7 · Adverbs of Manner & Frequency', 'Adjetivo vs. adverbio (-ly, well, fast, hard) y posición de adverbios de frecuencia', '🎯', 'multiple_choice', 'After verbs of perception like «look», «feel», «taste», and «smell», we use:', '["an adjective (e.g., This soup tastes great!)", "an adverb with -ly (e.g., This soup tastes greatly!)", "a noun only", "an infinitive"]'::jsonb, 'an adjective (e.g., This soup tastes great!)', 'Los verbos de los sentidos (taste, smell, look, sound, feel) van seguidos de adjetivo: «You look tired / It smells delicious».', 5),
  ('Adultos 2', 'L8', 'Lesson 8 · Modal Verbs: Ability, Advice & Obligation', 'Can, could, should, must, have to, may y might', '💡', 'multiple_choice', 'You look very pale and have a fever. You ___ see a doctor today.', '["should", "can''t", "may not", "could to"]'::jsonb, 'should', 'Para dar consejos o recomendaciones («deberías») usamos «should / shouldn''t» + verbo base.', 1),
  ('Adultos 2', 'L8', 'Lesson 8 · Modal Verbs: Ability, Advice & Obligation', 'Can, could, should, must, have to, may y might', '💡', 'multiple_choice', 'Passengers ___ wear a seatbelt during takeoff. It is mandatory by law.', '["must", "might", "could", "may"]'::jsonb, 'must', '«Must» y «have to» expresan obligación firme o reglas obligatorias.', 2),
  ('Adultos 2', 'L8', 'Lesson 8 · Modal Verbs: Ability, Advice & Obligation', 'Can, could, should, must, have to, may y might', '💡', 'multiple_choice', 'Tomorrow is a holiday, so we ___ wake up early! It''s not necessary.', '["don''t have to", "mustn''t", "can''t", "shouldn''t to"]'::jsonb, 'don''t have to', '«Don''t have to» significa «no es necesario»; en cambio «mustn''t» significa «está prohibido».', 3),
  ('Adultos 2', 'L8', 'Lesson 8 · Modal Verbs: Ability, Advice & Obligation', 'Can, could, should, must, have to, may y might', '💡', 'multiple_choice', 'When my grandfather was young, he ___ run a marathon in three hours.', '["could", "can", "may", "must"]'::jsonb, 'could', '«Could» expresa habilidad general en el pasado («podía / sabía»).', 4),
  ('Adultos 2', 'L8', 'Lesson 8 · Modal Verbs: Ability, Advice & Obligation', 'Can, could, should, must, have to, may y might', '💡', 'multiple_choice', 'Take a jacket with you because it ___ get cold later tonight.', '["might", "must", "should to", "has to"]'::jsonb, 'might', '«May» y «might» expresan posibilidad futura no segura («puede que / tal vez»).', 5),
  ('Adultos 3', 'L1', 'Lesson 1 · Progressive Tenses (Present, Past & Future) & Stative Verbs', 'Los 3 tiempos continuos, verbos de estado (stative verbs) y acciones interrumpidas', '⚡', 'multiple_choice', 'I ___ her phone number, and I ___ she is telling the truth. (Stative verbs!)', '["know / believe", "am knowing / am believing", "knows / believing", "knew / am believing"]'::jsonb, 'know / believe', 'Los verbos de estado mental o posesión (know, believe, own, want, need) NO llevan «-ing»; se usan en forma simple.', 1),
  ('Adultos 3', 'L1', 'Lesson 1 · Progressive Tenses (Present, Past & Future) & Stative Verbs', 'Los 3 tiempos continuos, verbos de estado (stative verbs) y acciones interrumpidas', '⚡', 'multiple_choice', 'While the teacher ___ into the classroom, the students ___ loudly.', '["was walking / were talking", "walked / talked", "is walking / were talking", "will walk / talked"]'::jsonb, 'was walking / were talking', 'Dos acciones en progreso al mismo tiempo en el pasado usan Past Progressive (was/were + -ing).', 2),
  ('Adultos 3', 'L1', 'Lesson 1 · Progressive Tenses (Present, Past & Future) & Stative Verbs', 'Los 3 tiempos continuos, verbos de estado (stative verbs) y acciones interrumpidas', '⚡', 'multiple_choice', 'I ___ dinner when suddenly the lights ___ out.', '["was cooking / went", "cooked / were going", "am cooking / went", "was cooking / go"]'::jsonb, 'was cooking / went', 'La acción larga de fondo va en Past Progressive (was cooking) y la acción corta que interrumpe va en Simple Past (went).', 3),
  ('Adultos 3', 'L1', 'Lesson 1 · Progressive Tenses (Present, Past & Future) & Stative Verbs', 'Los 3 tiempos continuos, verbos de estado (stative verbs) y acciones interrumpidas', '⚡', 'multiple_choice', 'Don''t call me at 8:00 pm tomorrow because I ___ in the concert at that time.', '["will be singing", "am singing", "sang", "will sing"]'::jsonb, 'will be singing', 'Para una acción que estará en pleno progreso en una hora específica del futuro usamos Future Progressive (will be + -ing).', 4),
  ('Adultos 3', 'L1', 'Lesson 1 · Progressive Tenses (Present, Past & Future) & Stative Verbs', 'Los 3 tiempos continuos, verbos de estado (stative verbs) y acciones interrumpidas', '⚡', 'multiple_choice', 'Why does the sentence «She is always forgetting my birthday!» use Present Progressive?', '["To express an annoying habit or complaint", "Because it is a stative verb", "To talk about the past", "Because forget is irregular"]'::jsonb, 'To express an annoying habit or complaint', '«Always + Present Progressive» se usa en nivel avanzado para expresar una queja sobre un hábito que molesta.', 5),
  ('Adultos 3', 'L2', 'Lesson 2 · Perfect Tenses (Present, Past & Future)', 'Have/has + participio, had + participio, will have + participio, already/yet/since/for', '⏳', 'multiple_choice', 'We have lived in this city ___ 2018, so we have been here ___ several years.', '["since / for", "for / since", "since / since", "already / yet"]'::jsonb, 'since / for', '«Since» marca el punto de inicio en el tiempo (since 2018) y «for» marca la duración total (for several years).', 1),
  ('Adultos 3', 'L2', 'Lesson 2 · Perfect Tenses (Present, Past & Future)', 'Have/has + participio, had + participio, will have + participio, already/yet/since/for', '⏳', 'multiple_choice', 'By the time we arrived at the station, the train ___ already ___.', '["had / left", "has / left", "have / leave", "will have / left"]'::jsonb, 'had / left', 'El Past Perfect («had + participio») expresa una acción que ocurrió ANTES que otra acción pasada (arrived).', 2),
  ('Adultos 3', 'L2', 'Lesson 2 · Perfect Tenses (Present, Past & Future)', 'Have/has + participio, had + participio, will have + participio, already/yet/since/for', '⏳', 'multiple_choice', 'A: Have you finished the report ___? — B: Yes, I have ___ sent it to the manager.', '["yet / already", "already / yet", "since / for", "ever / never"]'::jsonb, 'yet / already', '«Yet» va al final de preguntas y negaciones; «already» va en afirmaciones entre have/has y el participio.', 3),
  ('Adultos 3', 'L2', 'Lesson 2 · Perfect Tenses (Present, Past & Future)', 'Have/has + participio, had + participio, will have + participio, already/yet/since/for', '⏳', 'multiple_choice', 'By December next year, she ___ graduated from university.', '["will have", "has", "had", "would have"]'::jsonb, 'will have', '«By + fecha futura» usa Future Perfect («will have + participio») para algo que ya se habrá completado.', 4),
  ('Adultos 3', 'L2', 'Lesson 2 · Perfect Tenses (Present, Past & Future)', 'Have/has + participio, had + participio, will have + participio, already/yet/since/for', '⏳', 'multiple_choice', 'What is the difference between «She has gone to Madrid» and «She has been to Madrid»?', '["''Has gone'' means she is still in Madrid; ''has been'' means she visited and returned", "They mean the exact same thing", "''Has been'' means she is still there now", "''Has gone'' is past simple"]'::jsonb, '''Has gone'' means she is still in Madrid; ''has been'' means she visited and returned', '«Has gone to» = se fue y sigue allá; «has been to» = ha ido/visitado alguna vez y ya regresó.', 5),
  ('Adultos 3', 'L3', 'Lesson 3 · Countable & Uncountable Nouns, Containers & Quantifiers', 'Few vs. a few, little vs. a little, containers y sustantivos incontables avanzados', '🛒', 'multiple_choice', 'Be careful! In English, «advice», «information», «furniture», and «luggage» are:', '["Uncountable nouns (singular verb, no plural -s)", "Countable plural nouns", "Verbs", "Adjectives"]'::jsonb, 'Uncountable nouns (singular verb, no plural -s)', 'En inglés «advice, information, furniture, luggage, news, bread» son SIEMPRE incontables (decimos «a piece of advice», nunca «advices»).', 1),
  ('Adultos 3', 'L3', 'Lesson 3 · Countable & Uncountable Nouns, Containers & Quantifiers', 'Few vs. a few, little vs. a little, containers y sustantivos incontables avanzados', '🛒', 'multiple_choice', 'I have ___ close friends here, so I feel happy and never lonely.', '["a few", "a little", "little", "much"]'::jsonb, 'a few', '«A few» (unos cuantos, sentido positivo) se usa con sustantivos contables en plural («friends»).', 2),
  ('Adultos 3', 'L3', 'Lesson 3 · Countable & Uncountable Nouns, Containers & Quantifiers', 'Few vs. a few, little vs. a little, containers y sustantivos incontables avanzados', '🛒', 'multiple_choice', 'Hurry up! We have very ___ time left before the flight closes.', '["little", "few", "many", "a few"]'::jsonb, 'little', '«Little» (casi nada de, sentido negativo/escaso) se usa con sustantivos incontables como «time».', 3),
  ('Adultos 3', 'L3', 'Lesson 3 · Countable & Uncountable Nouns, Containers & Quantifiers', 'Few vs. a few, little vs. a little, containers y sustantivos incontables avanzados', '🛒', 'multiple_choice', 'Can you buy a ___ of bread and two ___ of toothpaste at the supermarket?', '["loaf / tubes", "slice / loaves", "bar / cans", "jar / cartons"]'::jsonb, 'loaf / tubes', 'Los envases/medidas exactos son: «a loaf of bread» (una barra/pan entero) y «a tube of toothpaste» (un tubo de pasta dental).', 4),
  ('Adultos 3', 'L3', 'Lesson 3 · Countable & Uncountable Nouns, Containers & Quantifiers', 'Few vs. a few, little vs. a little, containers y sustantivos incontables avanzados', '🛒', 'multiple_choice', 'How ___ pieces of luggage did you bring on the trip?', '["many", "much", "little", "amount"]'::jsonb, 'many', 'Aunque «luggage» es incontable, la palabra «pieces» es contable plural, por lo que usamos «How many pieces of...».', 5),
  ('Adultos 3', 'L4', 'Lesson 4 · Conditionals: Zero, First, Second, Third & Mixed', 'Los 4 condicionales (0, 1st, 2nd, 3rd) y condicionales mixtos', '🔀', 'multiple_choice', 'First Conditional (Real future possibility): If it ___ tomorrow, we ___ the event indoors.', '["rains / will hold", "will rain / hold", "rained / would hold", "had rained / would have held"]'::jsonb, 'rains / will hold', 'En el 1er Condicional, la cláusula con «If» va en Presente Simple (rains) y el resultado va con «will + verbo».', 1),
  ('Adultos 3', 'L4', 'Lesson 4 · Conditionals: Zero, First, Second, Third & Mixed', 'Los 4 condicionales (0, 1st, 2nd, 3rd) y condicionales mixtos', '🔀', 'multiple_choice', 'Second Conditional (Hypothetical present): If I ___ you, I ___ accept that job offer immediately.', '["were / would", "was / will", "am / would", "had been / would"]'::jsonb, 'were / would', 'En el 2do Condicional (hipotético) usamos «If I were you...» con «would + verbo base».', 2),
  ('Adultos 3', 'L4', 'Lesson 4 · Conditionals: Zero, First, Second, Third & Mixed', 'Los 4 condicionales (0, 1st, 2nd, 3rd) y condicionales mixtos', '🔀', 'multiple_choice', 'Third Conditional (Impossible past regret): If you ___ me earlier, I ___ helped you.', '["had called / would have", "called / would have", "had called / would", "would have called / had"]'::jsonb, 'had called / would have', 'El 3er Condicional habla del pasado irreal: «If + Past Perfect (had called) → would have + participio (helped)».', 3),
  ('Adultos 3', 'L4', 'Lesson 4 · Conditionals: Zero, First, Second, Third & Mixed', 'Los 4 condicionales (0, 1st, 2nd, 3rd) y condicionales mixtos', '🔀', 'multiple_choice', 'Zero Conditional (Scientific truth): If you ___ water to 100°C, it ___.', '["heat / boils", "heated / would boil", "will heat / boils", "heat / will boiled"]'::jsonb, 'heat / boils', 'Para leyes científicas y hechos universales (Zero Conditional) usamos Presente Simple en ambas partes.', 4),
  ('Adultos 3', 'L4', 'Lesson 4 · Conditionals: Zero, First, Second, Third & Mixed', 'Los 4 condicionales (0, 1st, 2nd, 3rd) y condicionales mixtos', '🔀', 'multiple_choice', 'We will go to the beach ___ it rains. («a menos que»)', '["unless", "if", "as long as", "because"]'::jsonb, 'unless', '«Unless» significa «if not» (a menos que / salvo que).', 5),
  ('Adultos 3', 'L5', 'Lesson 5 · Perfect Continuous Tenses', 'Present, Past & Future Perfect Continuous (have/had/will have been + -ing)', '🏃', 'multiple_choice', 'Her eyes are red because she ___ for two hours.', '["has been crying", "is crying", "cried", "had cried"]'::jsonb, 'has been crying', 'Present Perfect Continuous («has been + -ing») enfatiza la duración de una acción reciente cuya evidencia es visible ahora.', 1),
  ('Adultos 3', 'L5', 'Lesson 5 · Perfect Continuous Tenses', 'Present, Past & Future Perfect Continuous (have/had/will have been + -ing)', '🏃', 'multiple_choice', 'We ___ for the bus for 40 minutes when it finally arrived.', '["had been waiting", "have been waiting", "were waiting", "will have been waiting"]'::jsonb, 'had been waiting', 'Past Perfect Continuous («had been + -ing») muestra cuánto tiempo llevaba ocurriendo algo antes de otro evento pasado (arrived).', 2),
  ('Adultos 3', 'L5', 'Lesson 5 · Perfect Continuous Tenses', 'Present, Past & Future Perfect Continuous (have/had/will have been + -ing)', '🏃', 'multiple_choice', 'By next June, Professor Molina ___ at our academy for ten years.', '["will have been teaching", "has been teaching", "had been teaching", "is teaching"]'::jsonb, 'will have been teaching', 'Future Perfect Continuous («will have been + -ing») proyecta la duración acumulada de una acción hasta un momento del futuro.', 3),
  ('Adultos 3', 'L5', 'Lesson 5 · Perfect Continuous Tenses', 'Present, Past & Future Perfect Continuous (have/had/will have been + -ing)', '🏃', 'multiple_choice', 'How long ___ you ___ English?', '["have / been learning", "are / learning", "did / learn", "had / learning"]'::jsonb, 'have / been learning', 'Con «How long...?» para una acción que empezó en el pasado y continúa hoy, usamos «have/has been + -ing».', 4),
  ('Adultos 3', 'L5', 'Lesson 5 · Perfect Continuous Tenses', 'Present, Past & Future Perfect Continuous (have/had/will have been + -ing)', '🏃', 'multiple_choice', 'Which verb CANNOT be used in the Perfect Continuous form because it is stative?', '["know (I have known her for years)", "work (I have been working)", "study (She has been studying)", "wait (We have been waiting)"]'::jsonb, 'know (I have known her for years)', 'Los verbos de estado como «know, believe, own» nunca llevan «-ing», por lo que usan Present Perfect Simple («I have known»).', 5),
  ('Adultos 3', 'L6', 'Lesson 6 · Causative & Permission: Make, Let & Be Allowed To', 'Obligar (make someone do), permitir (let someone do) y tener permiso (be allowed to)', '🚦', 'multiple_choice', 'My parents ___ me clean my room before going out with my friends.', '["made", "let to", "allowed", "forced"]'::jsonb, 'made', 'Con «make» y «let» usamos objeto + verbo base SIN «to»: «made me clean» (me obligaron/hicieron limpiar).', 1),
  ('Adultos 3', 'L6', 'Lesson 6 · Causative & Permission: Make, Let & Be Allowed To', 'Obligar (make someone do), permitir (let someone do) y tener permiso (be allowed to)', '🚦', 'multiple_choice', 'Our teacher ___ us use a dictionary during the writing practice.', '["let", "allowed", "made to", "permitted"]'::jsonb, 'let', '«Let + persona + verbo sin to» expresa permiso activo («let us use»). Con «allow» sería «allowed us TO use».', 2),
  ('Adultos 3', 'L6', 'Lesson 6 · Causative & Permission: Make, Let & Be Allowed To', 'Obligar (make someone do), permitir (let someone do) y tener permiso (be allowed to)', '🚦', 'multiple_choice', 'Visitors ___ take flash photographs inside the art museum.', '["are not allowed to", "don''t let to", "aren''t make to", "not allowed"]'::jsonb, 'are not allowed to', 'La estructura pasiva de permiso lleva siempre «to»: «be (not) allowed to + verbo base».', 3),
  ('Adultos 3', 'L6', 'Lesson 6 · Causative & Permission: Make, Let & Be Allowed To', 'Obligar (make someone do), permitir (let someone do) y tener permiso (be allowed to)', '🚦', 'multiple_choice', 'That sad movie ___ everyone in the theater cry.', '["made", "allowed", "let to", "caused"]'::jsonb, 'made', '«Make someone + verbo base» también significa causar una reacción emocional («made everyone cry»).', 4),
  ('Adultos 3', 'L6', 'Lesson 6 · Causative & Permission: Make, Let & Be Allowed To', 'Obligar (make someone do), permitir (let someone do) y tener permiso (be allowed to)', '🚦', 'multiple_choice', 'In passive voice, «The boss made him stay late» becomes: «He was made ___ late.»', '["to stay", "stay", "staying", "stayed"]'::jsonb, 'to stay', 'Importante matiz avanzado: cuando «make» pasa a voz pasiva («was made»), SÍ recupera la partícula «to» («was made to stay»).', 5),
  ('Adultos 3', 'L7', 'Lesson 7 · Reported Speech (Indirect Speech)', 'Cambio de tiempos verbales (backshift), say vs. tell y preguntas reportadas', '🗣️', 'multiple_choice', 'Direct: «I am working on a project.» → Reported: She said that she ___ on a project.', '["was working", "is working", "has been working", "will be working"]'::jsonb, 'was working', 'En Reported Speech los tiempos retroceden un paso al pasado (backshift): Present Progressive (am working) → Past Progressive (was working).', 1),
  ('Adultos 3', 'L7', 'Lesson 7 · Reported Speech (Indirect Speech)', 'Cambio de tiempos verbales (backshift), say vs. tell y preguntas reportadas', '🗣️', 'multiple_choice', 'Direct: «I will call you tomorrow.» → He told me that he ___ call me the next day.', '["would", "will", "can", "shall"]'::jsonb, 'would', 'Al reportar en pasado, «will» cambia a «would» y «tomorrow» cambia a «the next day / the following day».', 2),
  ('Adultos 3', 'L7', 'Lesson 7 · Reported Speech (Indirect Speech)', 'Cambio de tiempos verbales (backshift), say vs. tell y preguntas reportadas', '🗣️', 'multiple_choice', 'What is the grammar difference between «say» and «tell» in Reported Speech?', '["''Tell'' requires a personal object (told me); ''say'' does not (said that...)", "''Say'' requires a personal object (said me)", "They are used identically", "''Tell'' is only for questions"]'::jsonb, '''Tell'' requires a personal object (told me); ''say'' does not (said that...)', 'Decimos «She told ME that...» (con receptor) o «She said that...» (nunca «She said me»).', 3),
  ('Adultos 3', 'L7', 'Lesson 7 · Reported Speech (Indirect Speech)', 'Cambio de tiempos verbales (backshift), say vs. tell y preguntas reportadas', '🗣️', 'multiple_choice', 'Direct question: «Where do you live?» → She asked me where ___.', '["I lived", "did I live", "do I live", "lived I"]'::jsonb, 'I lived', 'Las preguntas reportadas usan el orden afirmativo (sujeto + verbo en pasado) y NO usan el auxiliar do/did: «where I lived».', 4),
  ('Adultos 3', 'L7', 'Lesson 7 · Reported Speech (Indirect Speech)', 'Cambio de tiempos verbales (backshift), say vs. tell y preguntas reportadas', '🗣️', 'multiple_choice', 'Direct Yes/No question: «Are you ready?» → He asked us ___ we were ready.', '["if / whether", "that", "what", "who"]'::jsonb, 'if / whether', 'Cuando reportamos una pregunta cerrada (Yes/No), conectamos con «if» o «whether» («He asked us if we were ready»).', 5),
  ('Adultos 3', 'L8', 'Lesson 8 · Passive Voice & Modals of Deduction', 'Voz pasiva en todos los tiempos y deducción lógica (must/can''t/might have + participio)', '⚖️', 'multiple_choice', 'Active: «Gabriel García Márquez wrote One Hundred Years of Solitude.» → Passive:', '["One Hundred Years of Solitude was written by G. G. Márquez.", "One Hundred Years of Solitude wrote by G. G. Márquez.", "One Hundred Years of Solitude has written by G. G. Márquez.", "One Hundred Years of Solitude is wrote by G. G. Márquez."]'::jsonb, 'One Hundred Years of Solitude was written by G. G. Márquez.', 'La voz pasiva en pasado simple se forma con «was / were + past participle» (was written by...).', 1),
  ('Adultos 3', 'L8', 'Lesson 8 · Passive Voice & Modals of Deduction', 'Voz pasiva en todos los tiempos y deducción lógica (must/can''t/might have + participio)', '⚖️', 'multiple_choice', 'The new hospital ___ built right now; it will open next year.', '["is being", "is", "has been", "was"]'::jsonb, 'is being', 'En Present Continuous Passive («está siendo construido») usamos «am/is/are + being + participio».', 2),
  ('Adultos 3', 'L8', 'Lesson 8 · Passive Voice & Modals of Deduction', 'Voz pasiva en todos los tiempos y deducción lógica (must/can''t/might have + participio)', '⚖️', 'multiple_choice', 'The ground is completely wet this morning. It ___ rained heavily last night!', '["must have", "can''t have", "should", "must to"]'::jsonb, 'must have', 'Para una deducción casi 100% segura sobre el pasado usamos «must have + participio».', 3),
  ('Adultos 3', 'L8', 'Lesson 8 · Passive Voice & Modals of Deduction', 'Voz pasiva en todos los tiempos y deducción lógica (must/can''t/might have + participio)', '⚖️', 'multiple_choice', 'You ___ seen María at the mall yesterday because she is in Spain all month!', '["can''t have", "must have", "should have", "may have"]'::jsonb, 'can''t have', 'Para deducir que algo fue lógicamente imposible en el pasado usamos «can''t have / couldn''t have + participio».', 4),
  ('Adultos 3', 'L8', 'Lesson 8 · Passive Voice & Modals of Deduction', 'Voz pasiva en todos los tiempos y deducción lógica (must/can''t/might have + participio)', '⚖️', 'multiple_choice', 'All safety protocols must ___ respected by the staff.', '["be", "been", "being", "to be"]'::jsonb, 'be', 'Con verbos modales en voz pasiva la estructura es «modal + be + past participle» (must be respected).', 5),
  ('Adultos 3', 'L9', 'Lesson 9 · Phrasal Verbs in Context', 'Verbos compuestos separables e inseparables para la vida diaria y el trabajo', '🧩', 'multiple_choice', 'We need to stop at the gas station before we ___ fuel!', '["run out of", "look after", "give up", "turn off"]'::jsonb, 'run out of', '«Run out of» significa quedarse sin algo o agotarse (run out of fuel / time / money).', 1),
  ('Adultos 3', 'L9', 'Lesson 9 · Phrasal Verbs in Context', 'Verbos compuestos separables e inseparables para la vida diaria y el trabajo', '🧩', 'multiple_choice', 'Never ___ on your dreams! Keep practicing every day.', '["give up", "put off", "take off", "find out"]'::jsonb, 'give up', '«Give up» significa rendirse o abandonar un hábito.', 2),
  ('Adultos 3', 'L9', 'Lesson 9 · Phrasal Verbs in Context', 'Verbos compuestos separables e inseparables para la vida diaria y el trabajo', '🧩', 'multiple_choice', 'Can you ___ my dog this weekend while I am traveling?', '["look after", "look for", "look up", "look forward to"]'::jsonb, 'look after', '«Look after» = cuidar a alguien; «look for» = buscar; «look up» = buscar información en un diccionario/lista.', 3),
  ('Adultos 3', 'L9', 'Lesson 9 · Phrasal Verbs in Context', 'Verbos compuestos separables e inseparables para la vida diaria y el trabajo', '🧩', 'multiple_choice', 'With separable phrasal verbs like «turn off», which sentence is grammatically INCORRECT?', '["Turn off it.", "Turn it off.", "Turn the light off.", "Turn off the light."]'::jsonb, 'Turn off it.', 'Cuando el objeto de un phrasal verb separable es un pronombre (it, them), DEBE ir en el medio: «Turn it off» (nunca «Turn off it»).', 4),
  ('Adultos 3', 'L9', 'Lesson 9 · Phrasal Verbs in Context', 'Verbos compuestos separables e inseparables para la vida diaria y el trabajo', '🧩', 'multiple_choice', 'Don''t ___ until tomorrow what you can do today!', '["put off", "call off", "get along", "bring up"]'::jsonb, 'put off', '«Put off» significa posponer o postergar; «call off» significa cancelar por completo.', 5),
  ('Adultos 3', 'L10', 'Lesson 10 · Relative Clauses (Who, Which, That, Whose, Where)', 'Cláusulas relativas especificativas y explicativas con who, which, whose, where, when', '🔗', 'multiple_choice', 'An architect is a professional ___ designs buildings and bridges.', '["who", "which", "whose", "where"]'::jsonb, 'who', 'Usamos «who» (o «that») para referirnos a personas.', 1),
  ('Adultos 3', 'L10', 'Lesson 10 · Relative Clauses (Who, Which, That, Whose, Where)', 'Cláusulas relativas especificativas y explicativas con who, which, whose, where, when', '🔗', 'multiple_choice', 'That is the woman ___ daughter won the national scholarship.', '["whose", "who", "which", "whom"]'::jsonb, 'whose', '«Whose» es el pronombre relativo posesivo («cuyo / cuya»): whose daughter = cuya hija.', 2),
  ('Adultos 3', 'L10', 'Lesson 10 · Relative Clauses (Who, Which, That, Whose, Where)', 'Cláusulas relativas especificativas y explicativas con who, which, whose, where, when', '🔗', 'multiple_choice', 'Mérida is the city ___ my grandparents met fifty years ago.', '["where", "which", "who", "whose"]'::jsonb, 'where', 'Para indicar el lugar donde ocurre una acción dentro de la cláusula relativa usamos «where».', 3),
  ('Adultos 3', 'L10', 'Lesson 10 · Relative Clauses (Who, Which, That, Whose, Where)', 'Cláusulas relativas especificativas y explicativas con who, which, whose, where, when', '🔗', 'multiple_choice', 'My laptop, ___ I bought last year, works extremely fast. (Note the commas!)', '["which", "that", "who", "where"]'::jsonb, 'which', 'En cláusulas relativas explicativas entre comas (non-defining), NO se puede usar «that»; para cosas usamos «which».', 4),
  ('Adultos 3', 'L10', 'Lesson 10 · Relative Clauses (Who, Which, That, Whose, Where)', 'Cláusulas relativas especificativas y explicativas con who, which, whose, where, when', '🔗', 'multiple_choice', 'The book ___ you recommended to me was fascinating.', '["that / which", "who", "whose", "where"]'::jsonb, 'that / which', 'Para objetos o cosas en cláusulas sin comas podemos usar tanto «that» como «which».', 5);
